const META_KEY='arcana.progress.v1';
let metaStorageError=false;
function loadMeta(){try{const data=JSON.parse(localStorage.getItem(META_KEY)||'null');return {crystals:Number.isSafeInteger(data?.crystals)&&data.crystals>=0?data.crystals:0,totalCrystals:Number.isSafeInteger(data?.totalCrystals)&&data.totalCrystals>=0?data.totalCrystals:0,unlocked:Array.isArray(data?.unlocked)?[...new Set(data.unlocked.filter(id=>Number.isInteger(id)&&id>=70&&id<1000))]:[],skills:Array.isArray(data?.skills)?data.skills:[],hpUpgrades:Number.isInteger(data?.hpUpgrades)?Math.max(0,Math.min(10,data.hpUpgrades)):0}}catch(e){metaStorageError=true;return {crystals:0,totalCrystals:0,hpUpgrades:0,unlocked:[]}}}
let meta=loadMeta();
function showStorageNotice(){let notice=document.querySelector('#storage-notice');if(!notice){notice=document.createElement('div');notice.id='storage-notice';notice.className='storage-notice';document.body.append(notice)}notice.textContent='魔晶石の保存を利用できません。この画面を閉じると進捗が失われる可能性があります。'}
function saveMeta(){try{localStorage.setItem(META_KEY,JSON.stringify(meta));metaStorageError=false;return true}catch(e){metaStorageError=true;showStorageNotice();return false}}
function upgradePrice(){return 10+meta.hpUpgrades*5}
function crystalExchange(){if(s)return;document.body.dataset.scene='exchange';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">CRYSTAL SANCTUARY</div><div class="seal">${icon('土')}</div><h1 style="font-size:38px">魔晶石交換所</h1><p>冒険で集めた魔晶石を、永続する力へ。<br>通常の戦闘勝利で3個、各層のボスの勝利で15個以上獲得します。</p><div class="crystal-badge">◇ ${meta.crystals} 魔晶石</div><p><button class="primary" onclick="cardCollection()">カードを永続解放 →</button></p><div class="legacy-upgrade"><h2>生命の刻印</h2><p>新しい冒険の最大HPを＋5。最大10回まで強化できます。</p><div class="upgrade-level">${'◆ '.repeat(meta.hpUpgrades)}${'◇ '.repeat(10-meta.hpUpgrades)}</div><p>現在の最大HP <b>${50+meta.hpUpgrades*5}</b> ／ 強化 ${meta.hpUpgrades} / 10</p><button class="primary" onclick="buyHpUpgrade()" ${meta.hpUpgrades>=10||meta.crystals<upgradePrice()?'disabled':''}>${meta.hpUpgrades>=10?'最大まで強化済み':`魔晶石 ${upgradePrice()}個で強化`}</button></div><p class="small">同じブラウザ・同じゲームファイルで進捗を保存します。<br>ブラウザの保存データを消去すると、魔晶石と永続強化も消えます。</p><button onclick="setup()">冒険の準備に戻る →</button></section>`}
function buyHpUpgrade(){if(s||meta.hpUpgrades>=10||meta.crystals<upgradePrice())return;meta.crystals-=upgradePrice();meta.hpUpgrades++;saveMeta();crystalExchange()}

const artAssets={tiles:Array.from({length:20},(_,i)=>'assets/art-'+i+'.png'),atlas:'assets/arcana-atlas.png',scene:'assets/sanctum.png'};
