const skillBranches=[{name:'鋼の道',symbol:'片手剣',nodes:[['blade1','剣技の基礎',8,'攻撃力＋1',{attack:1}],['blade2','鋼の熟練',12,'攻撃力＋1',{attack:1}],['blade3','戦士の生命',16,'最大HP＋10',{maxHp:10}],['blade4','戦神の覚醒',24,'行動上限＋1',{maxEnergy:1}]]},{name:'星の道',symbol:'光',nodes:[['arcane1','魔術の基礎',8,'魔力＋1',{magic:1}],['arcane2','星の知識',12,'魔力＋1',{magic:1}],['arcane3','癒しの祈り',16,'回復力＋2',{healing:2}],['arcane4','星界の覚醒',24,'マナ上限＋1',{maxMana:1}]]},{name:'守護の道',symbol:'防御',nodes:[['guard1','守りの基礎',8,'防御力＋1',{defense:1}],['guard2','不屈の生命',12,'最大HP＋10',{maxHp:10}],['guard3','鉄壁の意志',16,'防御力＋1',{defense:1}],['guard4','守護者の覚醒',24,'最大HP＋15、防御力＋1',{maxHp:15,defense:1}]]}];
function cleanSkills(data){const ids=Array.isArray(data)?data:[];const result=[];for(const branch of skillBranches){for(const node of branch.nodes){if(!ids.includes(node[0]))break;result.push(node[0])}}return result}
function characterStats(){const stats={attack:0,magic:0,defense:0,healing:0,maxHp:50+meta.hpUpgrades*5,maxEnergy:3,maxMana:3};for(const b of skillBranches)for(const n of b.nodes)if((meta.skills||[]).includes(n[0]))for(const [key,value] of Object.entries(n[4]))stats[key]+=value;return stats}
function statSummary(){const t=s?.stats||characterStats();return `<div class="character-stats">${[['攻撃力',t.attack],['魔力',t.magic],['防御力',t.defense],['回復力',t.healing],['最大HP',t.maxHp],['行動上限',t.maxEnergy],['マナ上限',t.maxMana]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`}
function skillTree(message=''){if(s){alert('スキル習得は冒険の準備画面で行ってください。');return}document.body.dataset.scene='skills';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">PATH OF AWAKENING</div><h1 style="font-size:38px">スキルツリー</h1><p>魔晶石で、冒険者の力を育てる。各系統は上から順に習得します。</p><span class="crystal-badge">◇ ${meta.crystals} 魔晶石 ／ 習得 ${(meta.skills||[]).length} / 12</span>${statSummary()}<div class="skill-branches">${skillBranches.map(b=>`<section class="skill-branch"><h2>${icon(b.symbol)} ${b.name}</h2>${b.nodes.map((n,i)=>{const done=(meta.skills||[]).includes(n[0]),ready=i===0||(meta.skills||[]).includes(b.nodes[i-1][0]);return `<div class="skill-node ${done?'learned':''}"><span class="skill-rank">${i+1}</span><h3>${n[1]}</h3><p>${n[3]}</p><button onclick="learnSkill('${n[0]}')" ${done||!ready||meta.crystals<n[2]?'disabled':''}>${done?'習得済み':!ready?'前のスキルが必要':`魔晶石 ${n[2]}個で習得`}</button></div>`}).join('')}</section>`).join('')}</div><p aria-live="polite">${message}</p><p class="small">攻撃力：武器・汎用の攻撃カードに加算。魔力：魔法の攻撃カードに加算。<br>追加ダメージは複数回攻撃の最初の1回に適用。防御力は敵の攻撃ごとにダメージを軽減します。<br>回復力はHP回復カードに加算。毒・HP消費は防御力で軽減されません。<br>習得内容はプロフィールに保存され、次の冒険にも引き継ぎます。</p><button onclick="setup()">冒険の準備へ →</button></section>`}
function learnSkill(id){if(s)return;for(const b of skillBranches){const i=b.nodes.findIndex(n=>n[0]===id);if(i<0)continue;const n=b.nodes[i];if((meta.skills||[]).includes(id)||meta.crystals<n[2]||(i>0&&!(meta.skills||[]).includes(b.nodes[i-1][0])))return;meta.crystals-=n[2];meta.skills=[...(meta.skills||[]),id];saveMeta();skillTree(n[1]+'を習得しました。');return}}

