function effectText(a){let t=[];if(a.hpCost)t.push(`HPを${a.hpCost}消費`);if(a.break)t.push(a.break>=999?'敵の防御をすべて解除':`敵の防御を${a.break}減らす`);if(a.hit)t.push(`${a.all?'敵全体に':''}${a.hit}ダメージ${a.times?`を${a.times}回`:''}`);if(a.block)t.push(`防御${a.block}`);if(a.heal)t.push(`HPを${a.heal}回復`);if(a.draw)t.push(`${a.draw}枚引く`);if(a.burn)t.push('火傷（2ダメージ×2ターン）');if(a.poison)t.push('毒（3ダメージ×2ターン）');if(a.weak)t.push(`敵の次の攻撃−${a.weak}`);if(a.pierce)t.push('防御無視');if(a.counter)t.push(`次の攻撃者に${a.counter}ダメージ`);if(a.drain)t.push('実ダメージの半分を回復');if(a.buff)t.push(`次の攻撃＋${a.buff}`);if(a.weaponBuff)t.push(`次の武器攻撃＋${a.weaponBuff}`);if(a.discount)t.push('次の武器コスト−1');if(a.carry)t.push(`防御を最大${a.carry}持ち越す`);if(a.evade)t.push('次の攻撃を1回無効化');if(a.cleanse)t.push('自分の状態異常を解除');return t.join('。')+'。'}
function expanded(g,n,c,e){add(g,n,c,effectText(e),e);const card=all[all.length-1];card.exclusive=true;card.goldPrice=20+c*10+(n.includes('奥義')?10:0);card.crystalPrice=4+c*3+(n.includes('奥義')?3:0)}
for(let k=0;k<70;k++){const w=weapons[k%6],j=Math.floor(k/6),rank=j%3,f=j%11;let e,c=1;
switch(f){case 0:e={hit:6+rank*2};break;case 1:e={hit:3+rank,times:2};break;case 2:e={block:5+rank*2,hit:2};break;case 3:e={hit:4+rank,break:4+rank*2};break;case 4:e={hit:5+rank,weak:2+rank};break;case 5:e={hit:4+rank,draw:1};break;case 6:e={block:5+rank,counter:3+rank};break;case 7:c=2;e={hit:6+rank*2,all:1};break;case 8:c=2;e={hit:7+rank*2,drain:1};break;case 9:e={block:4+rank,weaponBuff:3+rank};break;default:c=3;e={hit:18+rank*2};}
if(w==='短剣'&&f===0)e={hit:4+rank,poison:2};if(w==='弓'&&f===3)e.pierce=1;if(w==='戦槌'&&f===3)e.break=999;if(w==='槍'&&f===0)e.weak=2;
expanded(w,`${weaponThemes[w][j]}の${weaponForms[f]}`,c,e)}
for(let k=0;k<65;k++){const m=magics[k%7],j=Math.floor(k/7),r=j%3,f=j%10;let e,c=1;switch(f){case 0:e={hit:5+r*2};break;case 1:e={block:6+r*2};break;case 2:c=2;e={hit:6+r,all:1};break;case 3:e={heal:4+r,block:2};break;case 4:c=2;e={hit:4+r,times:2};break;case 5:e={hit:3+r,weak:3+r};break;case 6:e={draw:1,buff:2+r};break;case 7:c=2;e={hit:8+r*2,block:3};break;default:c=2;e={hit:10+r*2};}
if(m==='火'&&e.hit&&!e.times)e.burn=2;if(m==='氷'&&e.hit)e.weak=(e.weak||0)+2;if(m==='雷'&&e.hit)e.hit+=2;if(m==='風'&&f===6)e={draw:1,discount:1};if(m==='土'&&e.block){e.block+=3;e.carry=2}if(m==='光'&&f===3)e.cleanse=1;if(m==='闇'&&e.hit){e.hpCost=2;if(f%2===0)e.drain=1}
expanded(m,`${magicThemes[m][j]}の${magicForms[f]}`,c,e)}
const commonThemes=['旅人','傭兵','探索者','賢者','守護者','斥候','騎士','巡礼者','英雄','冒険王'];
const commonForms=['強打','備え','手当','観察','集中術','回避術','戦闘準備','活力','迎撃術','浄化薬'];
for(let k=0;k<95;k++){const j=Math.floor(k/10),f=k%10,r=j%4;let e,c=1;switch(f){case 0:e={hit:5+r};break;case 1:e={block:6+r};break;case 2:e={heal:4+r};break;case 3:e={draw:1,block:2+r};break;case 4:e={buff:4+r};break;case 5:c=2;e={evade:1,block:r};break;case 6:e={block:3+r,buff:2+r};break;case 7:c=2;e={heal:5+r,draw:1};break;case 8:e={block:4+r,counter:2+r};break;default:e={cleanse:1,heal:2+r};}expanded('汎用',`${commonThemes[j]}の${commonForms[f]}`,c,e)}
function owned(c){return !c.exclusive||meta.unlocked.includes(c.id)}

function card(c,action,disabled=false){return `<button class="card" ${disabled?'disabled':''} ${action?`onclick="${action}"`:''}><span class="type">${c.g}${c.e.once?' · 戦闘中1回':''}</span><span class="cost">${c.c}</span><span class="symbol">${groups[c.g][0]}</span><b>${c.n}</b><span class="desc">${c.d}</span></button>`}
function setup(){s=null;$('#app').innerHTML=`<section class="hero"><div class="eyebrow">A DECK. A WEAPON. YOUR DESTINY.</div><div class="seal">✧</div><h1>一枚の選択が、<br>運命を変える。</h1><p>武器と魔法を組み合わせ、忘れられた遺跡へ。<br>探索と戦闘を繰り返す、カードバトルRPG。</p></section><div class="setup"><section class="panel"><div class="eyebrow">01 / WEAPON</div><h2>武器を選ぶ</h2><div class="choices">${weapons.map(w=>`<button class="${weapon===w?'chosen':''}" onclick="weapon='${w}';setup()">${w}</button>`).join('')}</div><p class="small">${groups[weapon][1]}</p></section><section class="panel"><div class="eyebrow">02 / MAGIC</div><h2>魔法属性を選ぶ</h2><div class="choices">${magics.map(m=>`<button class="${magic===m?'chosen':''}" onclick="magic='${m}';setup()">${m}</button>`).join('')}</div><p class="small">${groups[magic][1]}</p></section></div><div class="start"><button class="primary" onclick="deckSetup()">デッキを組む →</button><p class="small">毎ターン 行動3 ＋ マナ3 / 手札5枚 / HP50<br>インストール不要・マウスやタップで操作</p></div>`}
function deckSetup(){picks=all.filter(c=>['汎用',weapon,magic].includes(c.g)&&owned(c)).map(c=>c.id);deckRender()}
function deckRender(){const pool=all.filter(c=>['汎用',weapon,magic].includes(c.g)&&owned(c));$('#app').innerHTML=`<div class="hero"><div class="eyebrow">BUILD YOUR DECK</div><h1 style="font-size:38px">冒険の準備</h1><p>${weapon} × ${magic} ／ 選択済み ${picks.length}枚<br>カードをクリックして採用・除外。10枚以上で出発できます。</p><button class="primary" onclick="start()" ${picks.length<10?'disabled':''}>遺跡へ出発 →</button> <button onclick="setup()">装備を変更</button></div><div class="cards">${pool.map(c=>card(c,`togglePick(${c.id})`)).join('')}</div>`;document.querySelectorAll('.cards .card').forEach((el,i)=>{if(picks.includes(pool[i].id))el.style.borderColor='#d4b678';else el.style.opacity='.4'})}
function togglePick(id){picks=picks.includes(id)?picks.filter(x=>x!==id):[...picks,id];deckRender()}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function start(){const stats=characterStats();s={stats,hp:stats.maxHp,max:stats.maxHp,gold:30,earned:0,stage:0,deck:[...picks],messages:[]};battle()}
function note(t){s.messages.unshift(t);s.messages=s.messages.slice(0,3)}
function battle(){let st=stages[s.stage];Object.assign(s,{block:0,carry:0,energy:3,mana:3,hand:[],pile:shuffle([...s.deck]),discard:[],used:[],turn:0,once:[],target:0,evade:0,reduce:0,counter:0,buff:0,weaponBuff:0,magicBuff:0,discount:0,noDraw:false,guard:false,pending:0,thunder:0,played:0,poison:0,enemies:[]});let count=s.stage===1||s.stage===2?2:1;for(let i=0;i<count;i++)s.enemies.push({n:st[1]+(count>1?` ${i+1}`:''),icon:st[2],hp:st[3],max:st[3],attack:st[4],block:s.stage===1?6:0,weak:0,burn:0,poison:0,freeze:0,vulnerable:0});note(`${st[0]}に足を踏み入れた。`);newTurn()}
function draw(n){if(s.noDraw)return;for(let i=0;i<n;i++){if(!s.pile.length)s.pile=shuffle(s.discard.splice(0));if(s.pile.length)s.hand.push(s.pile.pop())}}
function newTurn(){s.turn++;s.energy=s.stats.maxEnergy;s.mana=s.stats.maxMana;s.played=0;s.thunder=0;s.guard=false;s.noDraw=false;draw(5);render()}
function cost(c){return Math.max(0,c.c-(weapons.includes(c.g)?s.discount:0))}
function hurt(e,n,pierce=false){n=Math.max(0,n+e.vulnerable);const absorb=pierce?0:Math.min(e.block,n);e.block-=absorb;const actual=Math.min(e.hp,n-absorb);e.hp-=actual;return actual}
function resource(c){return magics.includes(c.g)?'mana':'energy'}
function can(c){return cost(c)<=s[resource(c)]&&s.hp>(c.e.hpCost||0)&&!(c.e.once&&s.once.includes(c.id))}
function play(i){if(!s||s.phase!=='battle')return;if(s.pending){s.discard.push(s.hand.splice(i,1)[0]);s.pending--;render();return}const c=all[s.hand[i]],a=c.e;if(!can(c))return;const targets=a.all?s.enemies.filter(e=>e.hp>0):[s.enemies[s.target]];if((a.hit||a.weak||a.freeze)&&!targets[0]?.hp)return;s[resource(c)]-=cost(c);if(weapons.includes(c.g))s.discount=0;s.hp-=a.hpCost||0;s.hand.splice(i,1);if(a.once||a.exhaust)s.once.push(c.id);else s.discard.push(c.id);if(a.recoverEnergy)s.energy=Math.min(s.stats.maxEnergy,s.energy+a.recoverEnergy);if(a.recoverMana)s.mana=Math.min(s.stats.maxMana,s.mana+a.recoverMana);let bonus=(magics.includes(c.g)?s.stats.magic+(s.stats.elementMagic||0):s.stats.attack)+s.buff+(weapons.includes(c.g)?s.weaponBuff:0)+(c.g==='雷'?s.magicBuff:0);let consume=Math.min(s.block,a.consume||0);s.block-=consume;let damage=0;for(const e of targets){if(a.hit&&s.stats.penetration)e.block=Math.max(0,e.block-s.stats.penetration);if(a.break)e.block=Math.max(0,e.block-a.break);if(a.hit){let n=a.hit+consume+(a.guardBonus&&s.guard?a.guardBonus:0)+(a.burnBonus&&e.burn?a.burnBonus:0)+(a.noBlockBonus&&!e.block?a.noBlockBonus:0)+(a.combo?Math.min(10,s.played*2):0)+(a.thunderCombo?Math.min(9,s.thunder*3):0);for(let j=0;j<(a.firstDouble&&s.played===0?2:(a.times||1));j++)damage+=criticalHit(e,n+(j===0?bonus:0),a.pierce,c)}if(a.weak)e.weak+=a.weak;if(a.burn)e.burn=2;if(a.poison)e.poison=2;if(a.freeze)e.freeze=1;if(a.vulnerable)e.vulnerable+=a.vulnerable}if(a.splash)for(const e of s.enemies)if(!targets.includes(e)&&e.hp>0)damage+=criticalHit(e,a.splash,false,c);if(a.hit){s.buff=0;if(weapons.includes(c.g))s.weaponBuff=0;if(c.g==='雷')s.magicBuff=0}if(a.block){s.block+=a.block;s.guard=true}if(a.heal||a.drain)s.hp=Math.min(s.max,s.hp+(a.heal?a.heal+s.stats.healing:0)+(a.drain?Math.floor(damage/2):0));if(a.cleanse)s.poison=0;for(const key of ['evade','reduce','counter','buff','weaponBuff','magicBuff','discount','carry'])if(a[key])s[key]+=a[key];if(a.noDraw)s.noDraw=true;draw(a.draw||0);s.pending=a.discard&&s.hand.length?1:0;s.played++;if(c.g==='雷')s.thunder++;note(`${c.n}${damage?`：${damage}ダメージ`:'を使用'}。`);if(winCheck())return;if(s.enemies[s.target].hp<=0)s.target=s.enemies.findIndex(e=>e.hp>0);render()}
function winCheck(){if(s.enemies.every(e=>e.hp<=0)){s.phase='reward';s.pending=0;const bounty=25+s.stage*10;s.gold+=bounty;s.earned+=bounty;s.lastBounty=bounty;const gems=s.stage===3?15:3;s.lastCrystals=gems;queueCrystals(gems,'battle');s.hp=Math.min(s.max,s.hp+10);if(s.stage===3){finish(true);return true}s.reward=shuffle(all.filter(c=>['汎用',weapon,magic].includes(c.g)&&owned(c))).slice(0,3).map(c=>c.id);reward();return true}return false}
function endTurn(){if(s.phase!=='battle'||s.pending)return;for(const e of s.enemies){e.vulnerable=0;if(e.hp<=0)continue;if(e.freeze){e.freeze=0;note(`${e.n}は凍結して動けない。`)}else if(e.healIntent){e.hp=Math.min(e.max,e.hp+6);note(`${e.n}はHPを6回復した。`)}else{let amount=Math.max(0,e.attack-e.weak-s.reduce-s.stats.defense);e.weak=0;s.reduce=0;if(Math.random()<(s.stats.dodge||0)){amount=0;note('敏捷性で攻撃を回避した。')}if(s.evade){s.evade--;amount=0}let absorb=Math.min(s.block,amount);s.block-=absorb;s.hp-=amount-absorb;note(`${e.n}の攻撃：${amount-absorb}ダメージ。`);if(s.counter){hurt(e,s.counter);s.counter=0}if(e.poisonAttack)s.poison=2}if(e.burn){e.hp=Math.max(0,e.hp-2);e.burn--}if(e.poison){e.hp=Math.max(0,e.hp-3);e.poison--}if(e.tactic===3||e.tactic===8)e.block=e.tactic===8?8:5;}if(s.poison){s.hp-=2;s.poison--;note('毒で2ダメージ。')}if(s.hp<=0){s.hp=0;finish(false);return}if(winCheck())return;s.discard.push(...s.hand);s.hand=[];s.block=Math.min(s.block,s.carry);s.carry=0;newTurn()}
function render(){s.phase='battle';$('#app').innerHTML=`<div class="topbar"><div><span class="eyebrow">CHAPTER ${s.stage+1} / 4</span><h2>${s.encounterSpec?.name||stages[s.stage][0]}</h2></div><div class="journey-wallet"><span class="gold-badge">◈ ${s.gold} G</span><span class="crystal-badge">◇ ${meta.crystals} 魔晶石</span><div class="progress">${'◆ '.repeat(s.stage+1)}${'◇ '.repeat(3-s.stage)}</div></div></div><div class="arena"><img class="arena-backdrop" src="${artAssets.scene}" alt="">${s.enemies.map((e,i)=>`<div role="button" tabindex="0" aria-label="${e.n}を選択" onclick="selectTarget(${i})" onkeydown="if(event.key==='Enter')selectTarget(${i})" class="enemy ${s.target===i?'target':''}" style="opacity:${e.hp?1:.25}"><div class="intent">${e.freeze?'凍結 · 次の行動停止':e.intent||`次の攻撃 ${Math.max(0,e.attack-e.weak-s.stats.defense)}`}</div><div class="monster">${artImage(e.portrait??(14+s.stage))}</div><b>${e.n}</b><div class="hp"><i style="width:${e.hp/e.max*100}%"></i></div><div class="small">HP ${e.hp} / ${e.max}　防御 ${e.block}</div><div class="small">${e.burn?icon('火')+' 火傷 ':''}${e.poison?icon('毒')+' 毒 ':''}${e.poisonAttack?'攻撃に毒付与':''}</div></div>`).join('')}</div><div class="stats"><div class="player-health"><div class="health-label">${icon('HP')} <span>HP</span> <strong>${s.hp}</strong><span>/ ${s.max}</span>${s.poison?' · 毒':''}</div><div class="player-hp ${s.hp/s.max<=.25?'critical':''}" role="progressbar" aria-label="プレイヤーHP" aria-valuemin="0" aria-valuemax="${s.max}" aria-valuenow="${s.hp}"><i style="width:${Math.max(0,Math.min(100,s.hp/s.max*100))}%"></i></div></div><span>${icon('防御')} 防御 <strong>${s.block}</strong></span><span class="energy-stat">${icon('汎用')} 行動 <strong>${s.energy}</strong> / ${s.stats.maxEnergy}</span><span class="mana-stat">${icon('光')} マナ <strong>${s.mana}</strong> / ${s.stats.maxMana}</span><button onclick="endTurn()" ${s.pending?'disabled':''}>ターン終了 →</button></div>${statSummary()}<div class="hint">${s.pending?'捨てるカードを1枚選んでください':`TURN ${s.turn} · 敵を選んでカードを使用 · 山札 ${s.pile.length} / 捨て札 ${s.discard.length}${s.discount?' · 次の武器コスト−1':''}${s.buff?' · 次の攻撃＋'+s.buff:''}`}</div><div class="log" aria-live="polite">${s.messages.join('<br>')}</div><div class="cards">${s.hand.map((id,i)=>card(all[id],`play(${i})`,!s.pending&&!can(all[id]))).join('')}</div><p class="hint">ターン終了時に手札を捨て、5枚引きます。山札が尽きると捨て札を混ぜ直します。<br>武器・汎用は行動、魔法はマナを消費。毎ターンそれぞれの上限まで回復します。<br>防御は次ターンに消失。奥義以外の強化は使用するまで持続します。</p>`}
function selectTarget(i){if(s.phase==='battle'&&s.enemies[i].hp>0){s.target=i;render()}}
function reward(){$('#app').innerHTML=`<section class="reward"><div class="eyebrow">VICTORY / CHAPTER ${s.stage+1}</div><div class="seal">✦</div><h1 style="font-size:42px">新たな力を、手に。</h1><p>戦闘に勝利！ HPを10回復、${s.lastBounty} Gを獲得。魔晶石${s.lastCrystals}個は終了時に精算します。<br>デッキに加えるカードを1枚選んでください。</p><div class="cards">${s.reward.map(id=>card(all[id],`next(${id})`)).join('')}</div><p><button onclick="next(-1)">カードを取らずに進む →</button></p><p class="small">現在HP ${s.hp} / ${s.max}　デッキ ${s.deck.length}枚　所持金 ${s.gold} G</p></section>`}
function next(id){if(s.phase!=='reward')return;if(id>=0)s.deck.push(id);s.shopStock=all.map(c=>({id:c.id,price:c.goldPrice||(c.n.startsWith('奥義')?50:30),bought:false}));marketPage=0;marketQuery='';s.phase='shop';shop()}
function finish(won){s.phase='end';$('#app').innerHTML=`<section class="hero" style="padding-top:75px"><div class="eyebrow">${won?'THE RUINS ARE LIBERATED':'YOUR JOURNEY CONTINUES'}</div><div class="seal">${won?'♛':'☽'}</div><h1>${won?'遺跡、踏破。':'冒険は、まだ終わらない。'}</h1><p>${won?'全4戦を突破しました。あなたの選択が、封印を解きました。':'力尽きました。装備とデッキを変えて、再び挑みましょう。'}<br>${weapon} × ${magic} ／ 到達 ${s.stage+1}戦目<br>所持金 ${s.gold} G ／ 今回獲得 ${s.earned} G<br>魔晶石 ${meta.crystals}個（次の冒険にも持ち越し）</p><button class="primary" onclick="setup()">もう一度遊ぶ →</button></section>`}
const artGroups=['汎用','片手剣','大剣','短剣','弓','槍','戦槌','火','氷','雷','風','土','光','闇'];
const colors=['#d8be83','#a9c3da','#c8aaa0','#b496d5','#9ebd86','#9bc5ca','#bba18b','#f59a66','#8dceef','#c3a8fa','#81d6ba','#c9ae76','#f3d58a','#b294ec'];
function artImage(i){return `<img class="single-art" src="${artAssets.tiles[i]}" alt="" draggable="false">`}
function artStyle(i){return `background-position:${(i%4)*100/3}% ${Math.floor(i/4)*25}%;`}
const paths={汎用:'M16 2 19 12 30 16 19 20 16 30 12 20 2 16 12 12Z',片手剣:'M23 3 29 3 29 9 12 26 6 20Z M5 17 15 27 M4 28 9 23',大剣:'M21 2 30 2 30 11 14 27 5 18Z M4 16 17 29 M3 29 8 24',短剣:'M7 3 14 10 7 22 2 17Z M19 8 27 2 30 7 22 20Z M2 22 12 27 M17 18 27 24 M4 28 7 24 M17 29 21 23',弓:'M9 3 Q31 16 9 29 L9 3 M3 16h26 M23 12l6 4-6 4',槍:'M24 2 30 2 30 8 22 13 19 10Z M22 10 3 29 M17 9l7 7',戦槌:'M13 3 29 9 24 20 8 14Z M15 16 6 29 M3 27l6 3',火:'M16 2C21 12 10 12 20 16 25 12 25 10 27 15 31 25 22 30 16 30 4 29 3 20 7 15 7 22 11 23 11 18 7 14 16 2Z',氷:'M16 2v28 M4 9l24 14 M4 23 28 9 M11 5l5 5 5-5 M11 27l5-5 5 5 M3 14l7-2-1-7 M23 27l-1-7 7-2',雷:'M19 2 6 18h9l-2 12L27 12h-10Z',風:'M3 9h18c9 0 9-9 2-7 M2 16h24c7 0 7 8 1 8 M5 23h12c7 0 7 7 1 7',土:'M16 2 29 12 24 28 8 28 3 12Z M16 2 10 14 16 28 22 14Z M3 12 10 14 M22 14 29 12',光:'M16 7a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M16 1v3 M16 28v3 M1 16h3 M28 16h3 M5 5l3 3 M24 24l3 3 M5 27l3-3 M24 8l3-3',闇:'M23 3A14 14 0 1 0 29 23 14 14 0 0 1 23 3Z M25 8v7 M21 12h8',HP:'M16 28 4 16C-3 6 10-1 16 8 22-1 35 6 28 16Z',防御:'M16 2 28 7v10c0 7-12 13-12 13S4 24 4 17V7Z M10 16l4 4 8-9',毒:'M7 18C-2 2 34 2 25 18l-3 2v7H10v-7Z M10 12h1 M21 12h1 M14 25v5 M18 25v5'};
function icon(g){return `<svg class="glyph" viewBox="0 0 32 32" aria-hidden="true"><path d="${paths[g]||paths.汎用}"/></svg>`}
card=function(c,action,disabled=false){const idx=artGroups.indexOf(c.g),ultimate=c.n.startsWith('奥義');return `<button class="card ${ultimate?'ultimate':''}" style="--accent:${colors[idx]}" ${disabled?'disabled':''} ${action?`onclick="${action}"`:''} aria-label="${c.n} ${magics.includes(c.g)?'マナ':'行動'}コスト${c.c} ${c.d}"><span class="type">${icon(c.g)} ${c.g}${ultimate?' / 奥義':''}</span><span class="cost ${magics.includes(c.g)?'mana-cost':'energy-cost'}" title="${magics.includes(c.g)?'マナ':'行動'}コスト">${c.c}<small>${magics.includes(c.g)?'MP':'AP'}</small></span><span class="card-art">${artImage(idx)}<span class="art-sigil">${icon(c.g)}</span></span><span class="card-title">${c.n}</span><span class="desc">${c.d}</span><span class="card-foot">${ultimate?'✦ LEGENDARY ART':'ARCANA · '+String(c.id+1).padStart(3,'0')}${c.e.once?' · 1回':''}</span></button>`};
setup=function(){s=null;document.body.dataset.scene='setup';$('#app').innerHTML=`<section class="hero"><div class="eyebrow">THE FORGOTTEN SANCTUM</div><div class="seal crest">${icon('汎用')}</div><h1>一枚の選択が、<br><em>運命</em>を変える。</h1><p>鋼を選べ。魔法を纏え。<br>忘れられた遺跡の、最後の封印を解き放て。</p><div class="hero-meta"><span>6 WEAPONS</span><i></i><span>7 ELEMENTS</span><i></i><span>${all.length} CARDS</span></div></section><div class="setup"><section class="panel"><div class="panel-art">${artImage(artGroups.indexOf(weapon))}</div><div class="panel-content"><div class="eyebrow">01 / CHOOSE YOUR WEAPON</div><h2>武器を選ぶ</h2><div class="choices">${weapons.map(w=>`<button class="${weapon===w?'chosen':''}" onclick="weapon='${w}';setup()">${icon(w)}<span>${w}</span></button>`).join('')}</div><p class="small">${groups[weapon][1]}</p></div></section><section class="panel"><div class="panel-art">${artImage(artGroups.indexOf(magic))}</div><div class="panel-content"><div class="eyebrow">02 / CHOOSE YOUR ELEMENT</div><h2>魔法を纏う</h2><div class="choices">${magics.map(m=>`<button style="--accent:${colors[artGroups.indexOf(m)]}" class="${magic===m?'chosen':''}" onclick="magic='${m}';setup()">${icon(m)}<span>${m}</span></button>`).join('')}</div><p class="small">${groups[magic][1]}</p></div></section></div><div class="start"><button class="primary" onclick="deckSetup()">デッキを組む <span>→</span></button><div class="legacy-summary"><span class="crystal-badge">◇ ${meta.crystals} 魔晶石</span><button onclick="crystalExchange()">魔晶石交換所</button><button onclick="skillTree()">スキルツリー / ステータス</button><span class="small">最大HP ${characterStats().maxHp} · Lvと6能力値は持ち越しなし</span></div><p class="small">行動3 ＋ マナ3 / 手札5枚 / 無限階層ダンジョン<br>開始資金300 G・勝利報酬でショップを利用<br>魔晶石は次の冒険にも持ち越し</p></div>`};
const baseRender=render;render=function(){document.body.dataset.scene='battle';baseRender();document.querySelectorAll('.seal').forEach(e=>e.innerHTML=icon('汎用'))};
const baseDeck=deckRender;deckRender=function(){document.body.dataset.scene='deck';baseDeck()};
const baseReward=reward;reward=function(){document.body.dataset.scene='reward';baseReward();$('.seal').innerHTML=icon('光')};
const baseFinish=finish;finish=function(w){document.body.dataset.scene='end';baseFinish(w);$('.seal').innerHTML=icon(w?'光':'闇')};

function shop(){document.body.dataset.scene='shop';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">THE WANDERING MERCHANT</div><div class="seal">${icon('汎用')}</div><h1 style="font-size:38px">遺跡の行商人</h1><p>次の戦いに備え、旅の報酬を力に変える。</p><div class="shop-status"><span class="gold-badge">◈ ${s.gold} G</span><span>HP ${s.hp} / ${s.max}</span><span>デッキ ${s.deck.length}枚</span></div>${marketControls('gold')}${marketGrid('gold')}<div class="shop-heal"><div><b>癒やしの泉</b><p class="small">HPを15回復。何度でも利用できます。</p></div><button onclick="buyHeal()" ${s.gold<20||s.hp>=s.max?'disabled':''}>20 G · 回復</button></div><p class="small">カード20〜60 G（カードごとに表示）<br>購入は現在の武器・魔法属性に対応するカードのみ<br>ゴールドは今回の冒険中のみ有効です。新しい冒険では初期デッキ購入後の残金から開始します。</p><button class="primary" onclick="leaveShop()">次の戦いへ →</button><div class="log" aria-live="polite">${s.shopMessage||'購入せずに次へ進むこともできます。'}</div></section>`}
function buyCard(i){if(s.phase!=='shop')return;const item=s.shopStock[i];if(!item||item.bought||s.gold<item.price)return;if(!['汎用',weapon,magic].includes(all[item.id].g)){s.shopMessage='このカードには対応する武器・魔法属性が必要です。';shop();return;}s.gold-=item.price;item.bought=true;s.deck.push(item.id);s.shopMessage=`${all[item.id].n}を購入。デッキに追加しました。`;shop()}
function buyHeal(){if(s.phase!=='shop'||s.gold<20||s.hp>=s.max)return;const amount=Math.min(15,s.max-s.hp);s.gold-=20;s.hp+=amount;s.shopMessage=`20 GでHPを${amount}回復しました。`;shop()}
function leaveShop(){if(s.phase!=='shop')return;s.shopMessage='';s.stage++;battle()}

if(metaStorageError)showStorageNotice();
let marketCategory='汎用',marketPage=0,marketQuery='';
function categoryOf(c){return weapons.includes(c.g)?'武器':magics.includes(c.g)?'魔法':'汎用'}
function marketControls(mode){return `<div class="market-controls"><div class="choices">${['汎用','武器','魔法'].map(v=>`<button class="${marketCategory===v?'chosen':''}" onclick="setMarket('${v}','${mode}')">${v}カード（${all.filter(c=>categoryOf(c)===v).length}枚）</button>`).join('')}</div><label>絞り込み <input aria-label="カード名や武器・属性で検索" placeholder="名前・武器・属性" value="${marketQuery.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}" onchange="searchMarket(this.value,'${mode}')"></label></div>`}
function setMarket(v,mode){marketCategory=v;marketPage=0;marketRefresh(mode)}function searchMarket(v,mode){marketQuery=v;marketPage=0;marketRefresh(mode)}function marketRefresh(mode){mode==='gold'?shop():cardCollection()}
function marketItems(mode){let items=mode==='gold'?s.shopStock.map((v,i)=>({...v,index:i})):all.map(c=>({id:c.id}));return items.filter(item=>categoryOf(all[item.id])===marketCategory&&(!marketQuery||`${all[item.id].n} ${all[item.id].g}`.includes(marketQuery)))}
function marketGrid(mode){const items=marketItems(mode),pages=Math.max(1,Math.ceil(items.length/12));marketPage=Math.max(0,Math.min(marketPage,pages-1));return `<div class="cards">${items.slice(marketPage*12,(marketPage+1)*12).map(item=>{const c=all[item.id];const unlocked=owned(c),price=mode==='gold'?item.price:c.crystalPrice;const unavailable=mode==='gold'?item.bought||s.gold<price:unlocked||meta.crystals<price;const action=mode==='gold'?`buyCard(${item.index})`:`unlockCard(${c.id})`;return `<div class="shop-item">${card(c,action,unavailable)}<button onclick="${action}" ${unavailable?'disabled':''}>${mode==='gold'?(item.bought?'購入済み':`${price} G · 今回の冒険に追加`):(unlocked?'解放済み':`魔晶石 ${price}個 · 永続解放`)}</button></div>`}).join('')}</div><div class="market-pagination"><button onclick="marketPage--;marketRefresh('${mode}')" ${marketPage===0?'disabled':''}>← 前へ</button><span>${items.length}枚 ／ ${marketPage+1} / ${pages}</span><button onclick="marketPage++;marketRefresh('${mode}')" ${marketPage>=pages-1?'disabled':''}>次へ →</button></div>`}
function cardCollection(){if(s)return;document.body.dataset.scene='exchange';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">PERMANENT CARD COLLECTION</div><h1 style="font-size:36px">魔晶石カード交換所</h1><p>解放したカードは、装備条件を満たすと冒険開始時のデッキ構築に使えます。</p><div class="crystal-badge">◇ ${meta.crystals} 魔晶石 ／ 解放 ${all.filter(owned).length} / ${all.length}</div>${marketControls('crystal')}${marketGrid('crystal')}<button onclick="crystalExchange()">永続強化へ</button> <button onclick="setup()">冒険の準備へ →</button></section>`}
function unlockCard(id){if(s)return;const c=all[id];if(!c||owned(c)||meta.crystals<c.crystalPrice)return;meta.crystals-=c.crystalPrice;meta.unlocked.push(id);saveMeta();cardCollection()}

let selectedSkill='blade1';
function skillPosition(branch,index){const angle=(-90+branch*120+[-9,-3,5,11][index])*Math.PI/180,radius=[13,23,33,43][index];return {x:50+Math.cos(angle)*radius,y:50+Math.sin(angle)*radius}}
function selectSkill(id){selectedSkill=id;skillTree()}
skillTree=function(message=''){if(s){alert('スキル習得は冒険の準備画面で行ってください。');return}document.body.dataset.scene='skills';let lines='',nodes='';const hues=['#e1b77f','#9baeff','#83ccb2'];for(let bi=0;bi<skillBranches.length;bi++){const b=skillBranches[bi];let previous={x:50,y:50};b.nodes.forEach((n,i)=>{const point=skillPosition(bi,i),done=(meta.skills||[]).includes(n[0]),ready=i===0||(meta.skills||[]).includes(b.nodes[i-1][0]);lines+=`<path class="${done?'active':''}" style="--branch-color:${hues[bi]}" d="M ${previous.x} ${previous.y} Q ${(previous.x+point.x)/2+2} ${(previous.y+point.y)/2} ${point.x} ${point.y}"/>`;nodes+=`<button class="radial-node ${done?'learned':ready?'available':'locked'} ${selectedSkill===n[0]?'selected':''}" style="left:${point.x}%;top:${point.y}%;--branch-color:${hues[bi]}" onclick="selectSkill('${n[0]}')" aria-label="${b.name}・${n[1]}・${done?'習得済み':ready?'習得可能':'未解放'}" aria-pressed="${selectedSkill===n[0]}"><span>${icon(b.symbol)}</span><small>${i+1}</small><span class="node-label">${n[1]}</span></button>`;previous=point;});}
let branch=skillBranches.find(b=>b.nodes.some(n=>n[0]===selectedSkill))||skillBranches[0];let index=branch.nodes.findIndex(n=>n[0]===selectedSkill);if(index<0)index=0;const chosen=branch.nodes[index],done=(meta.skills||[]).includes(chosen[0]),ready=index===0||(meta.skills||[]).includes(branch.nodes[index-1][0]);$('#app').innerHTML=`<section class="reward radial-reward"><div class="eyebrow">CONSTELLATION OF AWAKENING</div><h1 style="font-size:38px">スキルツリー</h1><p>中心から、あなたの力を枝分かれさせる。<br>光点を選び、中心に近いスキルから順に習得します。</p><span class="crystal-badge">◇ ${meta.crystals} 魔晶石 ／ 習得 ${(meta.skills||[]).length} / 12</span><div class="branch-legend">${skillBranches.map((b,i)=>`<span style="color:${hues[i]}">${icon(b.symbol)} ${b.name}</span>`).join('')}</div><div class="radial-tree"><svg class="skill-connections" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="13"/><circle cx="50" cy="50" r="23"/><circle cx="50" cy="50" r="33"/><circle cx="50" cy="50" r="43"/>${lines}</svg><div class="skill-core">${icon('汎用')}<span>覚醒の核</span></div>${nodes}</div><div class="skill-detail"><div><div class="eyebrow">${branch.name} / ${index+1}</div><h2>${chosen[1]}</h2><p>${chosen[3]}</p><span class="small">${done?'習得済み · 永続効果':!ready?`先に「${branch.nodes[index-1][1]}」を習得してください。`:meta.crystals<chosen[2]?'魔晶石が不足しています。':'習得すると次の冒険にも引き継ぎます。'}</span></div><button class="primary" onclick="learnSkill('${chosen[0]}')" ${done||!ready||meta.crystals<chosen[2]?'disabled':''}>${done?'習得済み':`魔晶石 ${chosen[2]}個で習得`}</button></div><p aria-live="polite">${message}</p>${statSummary()}<p class="small">攻撃力・魔力は対応する攻撃カードの最初の1回に加算。<br>防御力は敵の攻撃ごとに軽減、回復力はHP回復カードに加算します。</p><button onclick="setup()">冒険の準備へ →</button></section>`};

const skillParents={};
for(const b of skillBranches)b.nodes.forEach((n,i)=>skillParents[n[0]]=i?b.nodes[i-1][0]:null);
const advancedNames=[['剣閃','戦気','疾駆','鋼心','覇気','武練','闘魂','刃風','剣域','戦旗'],['星詠','魔導','霊知','月光','秘儀','天啓','光紋','詠唱','星環','霊脈'],['石心','守誓','護身','堅忍','盾壁','生命','不屈','守陣','鉄心','根源']];
for(let bi=0;bi<3;bi++){const b=skillBranches[bi],count=bi===0?30:29;for(let j=0;j<count;j++){const id=['blade','arcane','guard'][bi]+'-branch-'+j,depth=Math.floor(Math.log2(j+1)),rank=depth+1;let effect,description;if(bi===0){effect=j%3===0?{maxHp:3}:{attack:1};description=j%3===0?'最大HP＋3':'攻撃力＋1';}else if(bi===1){effect=j%3===0?{healing:1}:{magic:1};description=j%3===0?'回復力＋1':'魔力＋1';}else{effect=j%4===0?{defense:1}:{maxHp:3};description=j%4===0?'防御力＋1':'最大HP＋3';}b.nodes.push([id,advancedNames[bi][j%10]+'・'+['初伝','中伝','奥伝'][Math.floor(j/10)],8+rank*4,description,effect]);skillParents[id]=j===0?b.nodes[1][0]:['blade','arcane','guard'][bi]+'-branch-'+Math.floor((j-1)/2);}}
cleanSkills=function(data){const ids=new Set(Array.isArray(data)?data:[]),result=[];for(const b of skillBranches)for(const n of b.nodes){const parent=skillParents[n[0]];if(ids.has(n[0])&&(!parent||result.includes(parent)))result.push(n[0])}return result};
function skillById(id){for(const b of skillBranches){const n=b.nodes.find(n=>n[0]===id);if(n)return {branch:b,node:n}}}
function skillDepth(id){const p=skillParents[id];return p?skillDepth(p)+1:1}
function skillAvailable(id){return !skillParents[id]||(meta.skills||[]).includes(skillParents[id])}
function constellationPositions(){const map={};for(let bi=0;bi<3;bi++){const b=skillBranches[bi],tiers={};for(const n of b.nodes){const depth=skillDepth(n[0]);(tiers[depth]??=[]).push(n)}for(const [d,nodes] of Object.entries(tiers)){nodes.forEach((n,i)=>{const angle=(-90+bi*120+(nodes.length===1?0:-49+98*i/(nodes.length-1)))*Math.PI/180,r=5+Number(d)*5.7;map[n[0]]={x:50+Math.cos(angle)*r,y:50+Math.sin(angle)*r}})}}return map}
learnSkill=function(id){if(s)return;const found=skillById(id);if(!found)return;const n=found.node;if((meta.skills||[]).includes(id)||!skillAvailable(id)||meta.crystals<n[2])return;meta.crystals-=n[2];meta.skills=[...(meta.skills||[]),id];saveMeta();selectedSkill=id;skillTree(n[1]+'を習得しました。')};
skillTree=function(message=''){if(s){alert('スキル習得は冒険の準備画面で行ってください。');return}document.body.dataset.scene='skills';const positions=constellationPositions(),hues=['#e1b77f','#9baeff','#83ccb2'];let lines='',nodes='';visibleSkillBranches().forEach((b,bi)=>b.nodes.forEach(n=>{const point=positions[n[0]],parent=skillParents[n[0]],previous=parent?positions[parent]:{x:50,y:50},done=(meta.skills||[]).includes(n[0]),ready=skillAvailable(n[0]);lines+=`<path class="${done?'active':''}" style="--branch-color:${hues[bi]}" d="M ${previous.x} ${previous.y} L ${point.x} ${point.y}"/>`;nodes+=`<button class="radial-node ${done?'learned':ready?'available':'locked'} ${selectedSkill===n[0]?'selected':''}" style="left:${point.x}%;top:${point.y}%;--branch-color:${hues[bi]}" onclick="selectSkill('${n[0]}')" title="${n[1]}：${n[3]}" aria-label="${b.name}・${n[1]}・${done?'習得済み':ready?'前提達成':'未解放'}" aria-pressed="${selectedSkill===n[0]}">${icon(b.symbol)}</button>`}));const found=skillById(selectedSkill)||skillById('blade1'),n=found.node,done=(meta.skills||[]).includes(n[0]),ready=skillAvailable(n[0]),parent=skillById(skillParents[n[0]]);$('#app').innerHTML=`<section class="reward radial-reward"><div class="eyebrow">ONE HUNDRED PATHS OF AWAKENING</div><h1 style="font-size:38px">スキルツリー</h1><p>中心から広がる、100の力。武器6種・魔法7属性の専用ツリー。線でつながった前提スキルから習得します。</p><span class="crystal-badge">◇ ${meta.crystals} 魔晶石 ／ このツリーの習得 ${visibleSkillBranches().flatMap(b=>b.nodes).filter(n=>(meta.skills||[]).includes(n[0])).length} / 100</span>${specialTreeMenu()}<div class="branch-legend">${visibleSkillBranches().map((b,i)=>`<span style="color:${hues[i]}">${icon(b.symbol)} ${b.name} ${b.nodes.length}</span>`).join('')}</div><div class="constellation-scroll"><div class="radial-tree expanded-tree"><svg class="skill-connections" viewBox="0 0 100 100" aria-hidden="true">${[10.7,16.4,22.1,27.8,33.5,39.2,44.9].map(r=>`<circle cx="50" cy="50" r="${r}"/>`).join('')}${lines}</svg><div class="skill-core">${icon('汎用')}<span>覚醒の核</span></div>${nodes}</div></div><div class="skill-detail"><div><div class="eyebrow">${found.branch.name} / 深度 ${skillDepth(n[0])}</div><h2>${n[1]}</h2><p>${n[3]}</p><span class="small">${parent?'前提：'+parent.node[1]:'中心から習得可能'}<br>${done?'習得済み':!ready?'前提スキルを先に習得してください。':meta.crystals<n[2]?'魔晶石が不足しています。':'習得可能'}</span></div><button class="primary" onclick="learnSkill('${n[0]}')" ${done||!ready||meta.crystals<n[2]?'disabled':''}>${done?'習得済み':`魔晶石 ${n[2]}個で習得`}</button></div><p aria-live="polite">${message}</p>${statSummary()}<p class="small">全スキルは永続保存。攻撃力・魔力は攻撃カードの最初の1回に加算し、防御力は敵の攻撃ごとに軽減します。<br>スマートフォンでは円形ツリーを左右にスクロールできます。</p><button onclick="setup()">冒険の準備へ →</button></section>`};

const specialSkillNames={片手剣:['剣閃','受流','返刃','剣心','王剣','銀刃','剣陣','鋼誓','刃翼','剣聖'],大剣:['重斬','断山','覇剣','巨刃','破城','戦気','剛腕','斬嵐','天墜','絶剣'],短剣:['影刃','毒牙','夜歩','残影','瞬撃','密技','暗月','疾駆','影舞','黒刃'],弓:['遠射','鷹眼','星弓','矢嵐','狙撃','風読み','森弓','弦心','月矢','天弓'],槍:['龍突','迎撃','槍陣','穿牙','騎槍','飛燕','蒼尖','烈槍','長柄','天槍'],戦槌:['粉砕','震岳','鉄撃','重腕','破甲','金剛','鍛鉄','岩砕','轟打','神槌'],火:['紅蓮','熾火','焔竜','火鳥','燎原','焦熱','炎輪','灰燼','灼光','業火'],氷:['霜月','凍海','氷晶','白雪','氷槍','寒星','零界','銀霧','雪華','冬王'],雷:['紫電','轟雷','雷獣','電光','閃雷','天雷','嵐雲','鳴神','雷環','雷帝'],風:['翠風','旋嵐','蒼翼','風精','天翔','疾風','空鳴','流雲','風舞','嵐王'],土:['岩峰','地脈','金剛','砂塵','石獣','黒曜','山脈','地響','大地','地王'],光:['聖光','日輪','祈願','白耀','天啓','祝福','黎明','光翼','聖星','光王'],闇:['影月','深淵','夜魔','冥界','黒霧','暗星','幽冥','魔眼','夢影','闇王']};
for(const group of [...weapons,...magics]){const isMagic=magics.includes(group),prefix='special-'+(isMagic?'m'+magics.indexOf(group):'w'+weapons.indexOf(group)),branch={name:group+(isMagic?'魔法':'')+'の道',symbol:group,weapon:isMagic?null:group,magic:isMagic?group:null,nodes:[]};for(let i=0;i<100;i++){let effect,description;switch(i%10){case 2:case 7:effect={maxHp:2};description='最大HP＋2';break;case 4:effect={defense:1};description='防御力＋1';break;case 6:effect={healing:1};description='回復力＋1';break;default:effect=isMagic?{magic:1}:{attack:1};description=isMagic?'魔力＋1':'攻撃力＋1';}if(i===99){effect=isMagic?{magic:2,maxMana:1}:{attack:2,maxEnergy:1};description=isMagic?'魔力＋2、マナ上限＋1':'攻撃力＋2、行動上限＋1';}const id=prefix+'-'+i;branch.nodes.push([id,specialSkillNames[group][i%10]+'・'+['一','二','三','四','五','六','七','八','九','十'][Math.floor(i/10)],8+skillDepthForIndex(i)*4,description,effect]);skillParents[id]=i?prefix+'-'+Math.floor((i-1)/2):null;}skillBranches.push(branch)}
function skillDepthForIndex(i){return Math.floor(Math.log2(i+1))+1}
characterStats=function(){const stats={attack:0,magic:0,defense:0,healing:0,maxHp:50+meta.hpUpgrades*5,maxEnergy:3,maxMana:3};for(const b of skillBranches){if(b.weapon&&b.weapon!==weapon||b.magic&&b.magic!==magic)continue;for(const n of b.nodes)if((meta.skills||[]).includes(n[0]))for(const [key,value] of Object.entries(n[4]))stats[key]+=value;}return stats};
let activeSkillCategory='common';
function visibleSkillBranches(){return activeSkillCategory==='common'?skillBranches.filter(b=>!b.weapon&&!b.magic):skillBranches.filter(b=>b.symbol===activeSkillCategory&&(b.weapon||b.magic))}
function changeSkillCategory(value){activeSkillCategory=value;selectedSkill=visibleSkillBranches()[0].nodes[0][0];skillTree()}
function specialTreeMenu(){return `<div class="special-tree-menu"><label>表示するスキルツリー <select onchange="changeSkillCategory(this.value)"><option value="common" ${activeSkillCategory==='common'?'selected':''}>共通ツリー（100）</option>${[...weapons,...magics].map(g=>`<option value="${g}" ${activeSkillCategory===g?'selected':''}>${g}${magics.includes(g)?'魔法':'武器'}（100）</option>`).join('')}</select></label><p class="small">装備中：${weapon} × ${magic} ／ 専用スキルは対応する装備・属性で発動</p></div>`}
constellationPositions=function(){const map={},visible=visibleSkillBranches();for(let bi=0;bi<visible.length;bi++){const tiers={};for(const n of visible[bi].nodes){const depth=skillDepth(n[0]);(tiers[depth]??=[]).push(n)}for(const [depth,nodes] of Object.entries(tiers))nodes.forEach((n,i)=>{const single=visible.length===1,angle=(single?-90+360*(i+.5)/nodes.length:-90+bi*120+(nodes.length===1?0:-49+98*i/(nodes.length-1)))*Math.PI/180,r=5+Number(depth)*5.7;map[n[0]]={x:50+Math.cos(angle)*r,y:50+Math.sin(angle)*r}})}return map};

const rarities=[['コモン','#9ca6ad'],['アンコモン','#7abd8a'],['レア','#75aaff'],['エピック','#bd8cf4'],['レジェンダリー','#e5c477'],['ミシック','#eb7777'],['レリック','#ffffff']];
const gearCards=[];
for(let rank=0;rank<7;rank++){for(const w of weapons)gearCards.push({id:'weapon-'+w+'-'+rank,type:'武器',group:w,name:['旅人','緑誓','蒼星','紫月','王者','深紅','遺跡の遺産'][rank]+'の'+w,rank,stats:{attack:rank+1},gold:20+rank*20,crystals:4+rank*8});for(const [name,stats] of [['騎士の鎧',{maxHp:5*(rank+1)}],['守護の盾',{defense:rank+1}],['魔導の衣',{magic:rank+1}],['巡礼の外套',{healing:rank+1}]])gearCards.push({id:'armor-'+name+'-'+rank,type:'装備',group:'防御',name:rarities[rank][0]+'・'+name,rank,stats,gold:20+rank*20,crystals:4+rank*8});for(const [name,stats] of [['星詠みの指輪',{magic:rank+1}],['戦士の護符',{attack:rank+1}],['生命の首飾り',{maxHp:4*(rank+1)}],['癒しの腕輪',{healing:rank+1}]])gearCards.push({id:'accessory-'+name+'-'+rank,type:'アクセサリー',group:'汎用',name:rarities[rank][0]+'・'+name,rank,stats,gold:20+rank*20,crystals:4+rank*8});}
const starterGear=gearCards.filter(c=>c.rank===0&&(c.type==='武器'||c.id==='armor-騎士の鎧-0'||c.id==='accessory-星詠みの指輪-0')).map(c=>c.id);
function cleanGearIds(ids){return [...new Set((Array.isArray(ids)?ids:[]).filter(id=>gearCards.some(c=>c.id===id)))]}
function cleanLoadout(d,owned){const list=cleanGearIds(owned),valid=(id,type)=>list.includes(id)&&gearCards.find(c=>c.id===id)?.type===type;return {weapon:valid(d?.weapon,'武器')?d.weapon:'weapon-片手剣-0',armor:cleanGearIds(d?.armor).filter(id=>valid(id,'装備')).slice(0,2),accessories:cleanGearIds(d?.accessories).filter(id=>valid(id,'アクセサリー')).slice(0,2)}}
function ensureGear(){meta.gearOwned=[...new Set([...starterGear,...cleanGearIds(meta.gearOwned)])];meta.loadout=cleanLoadout(meta.loadout,meta.gearOwned);if(!s&&gearCards.find(c=>c.id===meta.loadout.weapon)?.group!==weapon)meta.loadout.weapon=meta.gearOwned.find(id=>gearCards.find(c=>c.id===id)?.type==='武器'&&gearCards.find(c=>c.id===id)?.group===weapon)||'weapon-'+weapon+'-0';}
function currentGearIds(){const l=s?.loadout||meta.loadout;return l?[l.weapon,...l.armor,...l.accessories]:[]}
const beforeGearStats=characterStats;characterStats=function(){ensureGear();const stats=beforeGearStats();for(const id of currentGearIds()){const c=gearCards.find(c=>c.id===id);if(c?.type==='武器'&&c.group!==weapon)continue;for(const [key,value] of Object.entries(c?.stats||{}))stats[key]+=value;}return stats};
let gearCategory='武器';
function gearText(c){const labels={attack:'攻撃力',magic:'魔力',defense:'防御力',maxHp:'最大HP',healing:'回復力'};return Object.entries(c.stats).map(([k,v])=>labels[k]+'＋'+v).join(' / ')}
function gearPanel(message=''){if(s&&s.phase!=='shop'){alert('装着変更は準備画面か戦闘の合間に行えます。');return}ensureGear();gearPage=Math.max(0,Math.min(gearPage,Math.max(0,Math.ceil(visibleGearCards().length/14)-1)));const owned=s?[...meta.gearOwned,...(s.gearOwned||[])]:meta.gearOwned,l=s?.loadout||meta.loadout;document.body.dataset.scene='gear';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">ARMORY / EQUIPMENT CARDS</div><h1 style="font-size:36px">装着カード</h1><p>武器1枠・装備2枠・アクセサリー2枠。装着カードは手札に入りません。<br>属性武器は同じ属性の魔法攻撃を強化します。</p><span class="crystal-badge">${s?'◈ '+s.gold+' G':'◇ '+meta.crystals+' 魔晶石'}</span><div class="gear-slots">${['weapon','armor','accessories'].map((key,i)=>`<div><b>${['武器 1枠','装備 2枠','アクセサリー 2枠'][i]}</b><p>${(key==='weapon'?[l.weapon]:l[key]).map(id=>{const c=gearCards.find(c=>c.id===id);return `<button style="color:${rarities[c.rank][1]}" onclick="unequipGear('${id}')">${c.name}${key==='weapon'?'':' ×'}</button>`}).join('')||'未装着'}</p></div>`).join('')}</div>${statSummary()}<div class="choices gear-tabs">${['武器','装備','アクセサリー'].map(t=>`<button class="${gearCategory===t?'chosen':''}" onclick="gearCategory='${t}';gearPage=0;gearPanel()">${t}</button>`).join('')}</div>${gearFilterControls()}<div class="cards">${visibleGearCards().slice(gearPage*14,(gearPage+1)*14).map(c=>{const have=owned.includes(c.id),equipped=currentGearIds().includes(c.id),incompatible=s&&c.type==='武器'&&c.group!==weapon;return `<div class="shop-item"><div class="card gear-card" style="--accent:${rarities[c.rank][1]}"><span class="type">${c.type}${c.element?' / '+c.element:''} / ${rarities[c.rank][0]}${c.cursed?' / 代償':''}</span><span class="card-art">${uniqueCardImage('gear-'+c.id)}</span><span class="card-title">${c.name}</span><span class="desc">${gearText(c)}</span><span class="card-foot" style="color:${rarities[c.rank][1]}">${rarities[c.rank][0]}</span></div><button onclick="${have?`equipGear('${c.id}')`:`buyGear('${c.id}')`}" ${equipped||incompatible||(!have&&(s?s.gold<c.gold:meta.crystals<c.crystals))?'disabled':''}>${equipped?'装着中':incompatible?'今回の武器では装着不可':have?'装着する':s?c.gold+' G · 今回だけ':c.crystals+' 魔晶石 · 永続所有'}</button></div>`}).join('')}</div>${gearPaging()}<p aria-live="polite">${message}</p><button onclick="${s?'shop()':'setup()'}">${s?'ショップ':'冒険の準備'}へ →</button></section>`}
function buyGear(id){if(s&&s.phase!=='shop')return;const c=gearCards.find(c=>c.id===id);if(!c)return;ensureGear();if(meta.gearOwned.includes(id)||(s?.gearOwned||[]).includes(id))return;if(s){if(s.gold<c.gold)return;s.gold-=c.gold;s.gearOwned=[...(s.gearOwned||[]),id]}else{if(meta.crystals<c.crystals)return;meta.crystals-=c.crystals;meta.gearOwned.push(id);saveMeta()}gearPanel(c.name+'を購入しました。装着すると効果が発動します。')}
function equipGear(id){if(s&&s.phase!=='shop')return;ensureGear();const c=gearCards.find(c=>c.id===id),owned=[...meta.gearOwned,...(s?.gearOwned||[])];if(!c||!owned.includes(id)||s&&c.type==='武器'&&c.group!==weapon)return;const l=s?.loadout||meta.loadout;if(c.type==='武器'){l.weapon=id;if(!s)weapon=c.group}else{const key=c.type==='装備'?'armor':'accessories';if(l[key].includes(id))return;if(l[key].length>=2){gearPanel('装着枠が満杯です。先に装着中のカードを外してください。');return}l[key].push(id)}refreshGearStats();if(!s)saveMeta();gearPanel('装着しました。')}
function unequipGear(id){if(s&&s.phase!=='shop')return;const l=s?.loadout||meta.loadout;if(l.weapon===id)return;l.armor=l.armor.filter(x=>x!==id);l.accessories=l.accessories.filter(x=>x!==id);refreshGearStats();if(!s)saveMeta();gearPanel('装着を解除しました。')}
function refreshGearStats(){if(s){s.stats=characterStats();s.max=s.stats.maxHp;s.hp=Math.min(s.hp,s.max)}}
const beforeGearStart=start;start=function(){ensureGear();beforeGearStart();s.gearOwned=[];s.loadout=JSON.parse(JSON.stringify(meta.loadout));s.stats=characterStats()};
const beforeGearSetup=setup;setup=function(){ensureGear();beforeGearSetup();const target=$('#app');target.innerHTML=target.innerHTML.replace('<div class="legacy-summary">','<div class="legacy-summary"><button onclick="gearPanel()">装着カード / 装備庫</button>')};
const beforeGearShop=shop;shop=function(){beforeGearShop();$('#app').innerHTML=$('#app').innerHTML.replace('<div class="shop-heal">','<p><button onclick="gearPanel()">装着カードを購入・装着 →</button></p><div class="shop-heal">')};

const elementWeaponNames={火:'紅蓮',氷:'氷晶',雷:'紫電',風:'翠嵐',土:'黒曜',光:'聖光',闇:'冥月'};
for(const w of weapons)for(const element of magics)for(let rank=0;rank<7;rank++){gearCards.push({id:'element-weapon-'+w+'-'+element+'-'+rank,type:'武器',group:w,element,name:elementWeaponNames[element]+'の'+w+'・'+rarities[rank][0],rank,stats:{attack:rank+1},elementPower:rank+1,gold:30+rank*20,crystals:6+rank*8})}
const baseElementStats=characterStats;characterStats=function(){const stats=baseElementStats();const loadout=s?.loadout||meta.loadout,item=gearCards.find(c=>c.id===loadout?.weapon);stats.weaponElement=item?.element||null;stats.elementMagic=item?.element===magic?item.elementPower:0;return stats};
const baseGearText=gearText;gearText=function(c){return baseGearText(c)+(c.element?' / '+c.element+'魔法の攻撃＋'+c.elementPower:'')};
let weaponElementFilter='all',weaponKindFilter='all',gearPage=0;
function visibleGearCards(){return gearCards.filter(c=>c.type===gearCategory&&(gearCategory!=='武器'||(weaponElementFilter==='all'||(weaponElementFilter==='neutral'?!c.element:c.element===weaponElementFilter))&&(weaponKindFilter==='all'||c.group===weaponKindFilter)))}
function setGearFilter(kind,value){if(kind==='element')weaponElementFilter=value;else weaponKindFilter=value;gearPage=0;gearPanel()}
function gearFilterControls(){if(gearCategory!=='武器')return '';return `<div class="market-controls"><label>武器種 <select onchange="setGearFilter('kind',this.value)">${['all',...weapons].map(v=>`<option value="${v}" ${v===weaponKindFilter?'selected':''}>${v==='all'?'全武器種':v}</option>`).join('')}</select></label><label>属性 <select onchange="setGearFilter('element',this.value)">${['all','neutral',...magics].map(v=>`<option value="${v}" ${v===weaponElementFilter?'selected':''}>${v==='all'?'全属性':v==='neutral'?'無属性':v}</option>`).join('')}</select></label></div>`}
function gearPaging(){const count=visibleGearCards().length,pages=Math.max(1,Math.ceil(count/14));return `<div class="market-pagination"><button onclick="gearPage--;gearPanel()" ${gearPage===0?'disabled':''}>← 前へ</button><span>${count}枚 ／ ${gearPage+1} / ${pages}</span><button onclick="gearPage++;gearPanel()" ${gearPage>=pages-1?'disabled':''}>次へ →</button></div>`}

