for(const c of gearCards){const key=c.type==='武器'?c.group+'/'+(c.element||'無'):Object.keys(uniqueGearNames).find(k=>c.id.startsWith((c.type==='装備'?'armor-':'accessory-')+k+'-'));const names=uniqueGearNames[key];if(!names||!names[c.rank])throw Error('名前未設定：'+c.id);c.name=names[c.rank];}
if(new Set(gearCards.map(c=>c.name)).size!==gearCards.length)throw Error('装着カードの名前が重複しています。');

const dungeonLength=12;
start=function(){ensureGear();const stats=characterStats();s={stats,hp:stats.maxHp,max:stats.maxHp,gold:30,earned:0,stage:0,deck:[...picks],messages:[],gearOwned:[],loadout:JSON.parse(JSON.stringify(meta.loadout)),depth:0,encounters:[],battlesWon:0};exploration()};
function dungeonHud(){return `<div class="dungeon-hud"><span>♥ HP ${s.hp} / ${s.max}</span><span>◈ ${s.gold} G</span><span>◇ ${meta.crystals} 魔晶石</span><span>武器 ${weapon} / 魔法 ${magic}</span></div>`}
function exploration(message=''){s.phase='explore';s.pending=0;document.body.dataset.scene='explore';$('#app').innerHTML=`<section class="reward dungeon-explore"><div class="eyebrow">THE FORGOTTEN SANCTUM / EXPLORATION</div><h1 style="font-size:38px">忘れられた遺跡</h1><p>霧の先に何が待つか、まだ分からない。</p>${dungeonHud()}<div class="dungeon-map">${Array.from({length:dungeonLength},(_,i)=>`<span class="${i<s.depth?'visited':''} ${i===s.depth?'current':''}" title="区画${i+1}">${i===11?'♛':i+1}</span>`).join('')}</div><div class="explore-scene"><img src="${artAssets.scene}" alt="霧に包まれた遺跡"><div><span class="eyebrow">${s.depth===11?'THE SEALED GUARDIAN':'CHOOSE YOUR PATH'}</span><h2>${s.depth===11?'最深部の封印扉':'二つの道が続いている'}</h2><p>${s.depth===11?'扉の向こうには、この遺跡の守護者が待っている。':'慎重に進むか、危険な道で報酬を狙うか。'}</p></div></div><p aria-live="polite">${message||'探索 → 戦闘またはイベント → 探索'}</p><div class="explore-actions">${s.depth===11?'<button class="primary" onclick="explorePath(\'boss\')">最深部のボスに挑む →</button>':`<button onclick="explorePath('quiet')"><b>静かな回廊</b><span>戦闘率40％ / 通常報酬</span></button><button onclick="explorePath('danger')"><b>魔物の痕跡を追う</b><span>戦闘率75％ / 戦闘報酬＋15 G</span></button>`}</div><p class="small">区画 ${s.depth} / ${dungeonLength} ／ 勝利 ${s.battlesWon}回<br>第6区画に行商人、最深部にボス。HPとデッキは探索中も引き継ぎます。</p></section>`}
function explorePath(path){if(s.phase!=='explore'||!['quiet','danger','boss'].includes(path))return;if(path==='boss'&&s.depth!==11)return;s.depth++;s.dangerBonus=path==='danger'?15:0;if(s.depth===12){s.encounters.push('ボス');s.stage=3;battle();return}if(s.depth===6){s.encounters.push('行商人');openDungeonShop();return}const combat=s.depth===1||Math.random()<(path==='danger'?.75:.4);if(combat){s.encounters.push('戦闘');s.stage=Math.min(2,Math.floor((s.depth-1)/4));battle()}else{const events=['spring','chest','altar','trap','merchant'];s.event=events[Math.floor(Math.random()*events.length)];s.encounters.push('イベント');if(s.event==='merchant')openDungeonShop();else dungeonEvent()}}
function openDungeonShop(){s.shopStock=all.map(c=>({id:c.id,price:c.goldPrice||(c.n.startsWith('奥義')?50:30),bought:false}));marketPage=0;marketQuery='';s.phase='shop';shop()}
function dungeonEvent(){s.phase='event';const details={spring:['苔むした泉','澄んだ水が、旅の疲れを癒してくれそうだ。','泉の水を飲む（HP＋15）','休息を取る（HP＋8）'],chest:['忘れられた宝箱','錆びた宝箱の奥から、金貨の光がこぼれている。','慎重に開ける（＋20 G）','封印をこじ開ける（HP−5、＋40 G）'],altar:['古い星の祭壇','微かな光が、石の祭壇に集まっている。','祈りを捧げる（魔晶石＋1）','供物を捧げる（15 Gで魔晶石＋3）'],trap:['崩れかけた橋','足元の石橋が、深い闇に向かって崩れ始めた。','急いで渡る（HP−5）','安全な道具を使う（10 G）']},d=details[s.event];document.body.dataset.scene='event';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">DUNGEON EVENT / ${s.depth}</div><div class="seal">${icon(s.event==='altar'?'光':'汎用')}</div><h1 style="font-size:36px">${d[0]}</h1><p>${d[1]}</p>${dungeonHud()}<div class="event-choices"><button onclick="resolveDungeonEvent(0)">${d[2]}</button><button onclick="resolveDungeonEvent(1)" ${(s.event==='altar'&&s.gold<15||s.event==='trap'&&s.gold<10)?'disabled':''}>${d[3]}</button></div></section>`}
function resolveDungeonEvent(choice){if(s.phase!=='event'||![0,1].includes(choice))return;if(s.event==='altar'&&choice===1&&s.gold<15||s.event==='trap'&&choice===1&&s.gold<10)return;let message='';switch(s.event){case 'spring':{const heal=Math.min(choice===0?15:8,s.max-s.hp);s.hp+=heal;message=`泉でHPを${heal}回復した。`;break}case 'chest':{const amount=choice===0?20:40;s.gold+=amount;s.earned+=amount;if(choice===1)s.hp=Math.max(0,s.hp-5);message=`宝箱から${amount} Gを入手した。`;break}case 'altar':{const gems=choice===0?1:3;if(choice===1)s.gold-=15;queueCrystals(gems,'battle');message=`祭壇から魔晶石を${gems}個授かった。`;break}case 'trap':if(choice===0)s.hp=Math.max(0,s.hp-5);else s.gold-=10;message=choice===0?'橋を渡ったが、HPを5失った。':'道具を使い、無傷で渡れた。';break;}if(!s.hp){finish(false);return}exploration(message)}
next=function(id){if(s.phase!=='reward')return;if(id>=0){if(!s.reward.includes(id))return;s.deck.push(id)}exploration('戦闘を終え、再び探索を続ける。')};
leaveShop=function(){if(s.phase!=='shop')return;s.shopMessage='';exploration('行商人に別れを告げ、探索に戻った。')};
const dungeonWinCheck=winCheck;winCheck=function(){if(s.phase!=='battle')return false;if(!s.enemies.every(e=>e.hp<=0))return false;s.battlesWon++;if(s.dangerBonus){s.gold+=s.dangerBonus;s.earned+=s.dangerBonus;s.dangerBonus=0}return dungeonWinCheck()};
const dungeonRender=render;render=function(){dungeonRender();$('#app').innerHTML=$('#app').innerHTML.replace('CHAPTER '+(s.stage+1)+' / 4','DUNGEON '+s.depth+' / '+dungeonLength)};
const dungeonFinish=finish;finish=function(won){dungeonFinish(won);$('#app').innerHTML=$('#app').innerHTML.replace('全4戦を突破しました。','最深部の守護者を倒し、ダンジョンを踏破しました。').replace('到達 '+(s.stage+1)+'戦目','到達区画 '+s.depth+' / '+dungeonLength+' ／ 戦闘勝利 '+s.battlesWon+'回')};

const battleFactions=['苔の番兵','石棺の亡者','影の狩人','氷晶の獣','焔の眷属','雷雲の精霊','砂の傀儡','月蝕の使徒','白銀の騎士','封印の守護者'];
const battleTactics=['先遣隊','双衛隊','群れ','盾衛隊','毒牙隊','突撃隊','癒し手','狂戦士','重装隊','精鋭隊'];
const battleCatalog=Array.from({length:100},(_,id)=>({id,name:battleFactions[Math.floor(id/10)]+'・'+battleTactics[id%10],faction:Math.floor(id/10),tactic:id%10,boss:Math.floor(id/10)===9}));
function encounterEnemies(spec){const count=spec.boss?1:[1,2,3,2,1,1,2,1,1,2][spec.tactic],scale=1+Math.floor((s.depth-1)/4)*.18;return Array.from({length:count},(_,i)=>{const hp=Math.round((spec.boss?78+spec.tactic*3:count===1?28+spec.faction*2:count===2?21+spec.faction:15+spec.faction)*scale);return {n:spec.name+(count>1?' '+(i+1):''),hp,max:hp,attack:0,baseAttack:spec.boss?11:count===1?6:count===2?4:3,block:spec.tactic===8?8:0,weak:0,burn:0,poison:0,freeze:0,vulnerable:0,tactic:spec.tactic,portrait:14+spec.faction%4,poisonAttack:false,healIntent:false}})}
function prepareEnemyIntent(e){const t=s.turn;e.poisonAttack=e.tactic===4;e.healIntent=e.tactic===6&&t%3===0;e.attack=e.healIntent?0:e.baseAttack+(e.tactic===5?(t%2===0?5:0):e.tactic===7?Math.min(8,t-1):e.tactic===9?2:0);e.intent=e.healIntent?'回復6':null;}
const contentBattle=battle; battle=function(){s.stats=characterStats();s.encounterSpec=s.nextBattleSpec||shuffle(battleCatalog.filter(b=>b.boss===(s.depth===12)))[0];s.nextBattleSpec=null;contentBattle();s.enemies=encounterEnemies(s.encounterSpec);s.target=0;s.enemies.forEach(prepareEnemyIntent);render()};
const contentNewTurn=newTurn;newTurn=function(){s.enemies?.forEach(e=>{if(e.tactic!==undefined){const turn=s.turn;s.turn=turn+1;prepareEnemyIntent(e);s.turn=turn}});contentNewTurn()};
const eventAreas=['苔の庭','月影の回廊','灰の礼拝堂','氷晶の洞窟','雷鳴の尖塔','風渡りの橋','黒曜の地下室','聖光の祭壇','冥月の墓所','星屑の書庫'];
const eventKinds=['泉','宝箱','祈祷碑','崩落路','行商人','古文書','鍛冶場','魔導石','生命樹','運命の骰子'];
const eventCatalog=Array.from({length:100},(_,id)=>({id,name:eventAreas[Math.floor(id/10)]+'の'+eventKinds[id%10],kind:id%10,rank:Math.floor(id/10),text:eventAreas[Math.floor(id/10)]+'を歩いていると、'+eventKinds[id%10]+'を見つけた。'}));
function eventChoices(e){const r=e.rank;return [
[{label:`水を飲む：HP＋${10+r}`,heal:10+r},{label:`泉を調べる：HP−3、${12+r} G`,damage:3,gold:12+r}],
[{label:`慎重に開ける：${15+r*2} G`,gold:15+r*2},{label:`封印を破る：HP−6、${35+r*2} G`,damage:6,gold:35+r*2}],
[{label:'祈る：魔晶石＋1',gems:1},{label:`供物を捧げる：${15+r} Gで魔晶石＋3`,cost:15+r,gems:3}],
[{label:`走り抜ける：HP−${3+Math.floor(r/3)}`,damage:3+Math.floor(r/3)},{label:'道具を使う：10 Gで無傷',cost:10}],
[{label:'行商人と取引する',shop:true},{label:'情報を聞いて先へ進む：5 G',gold:5}],
[{label:'研究する：20 Gでカード1枚',cost:20,card:1},{label:`古文書を売る：${10+r} G`,gold:10+r}],
[{label:'武器を研ぐ：25 Gで今回の攻撃力＋1',cost:25,attack:1},{label:'炉で休む：HP＋6',heal:6}],
[{label:'魔導石に触れる：25 Gで今回の魔力＋1',cost:25,magic:1},{label:'欠片を採取：魔晶石＋1',gems:1}],
[{label:'生命の実を食べる：最大HP＋3、HP＋3',maxHp:3,heal:3},{label:`薬草を採る：HP＋${8+r}`,heal:8+r}],
[{label:'運を試す：50％で30 G、失敗でHP−5',gamble:true},{label:'勝負を見送る：HP＋3',heal:3}]
][e.kind];}
const eventBaseStats=characterStats;characterStats=function(){const t=eventBaseStats();for(const [k,v] of Object.entries(s?.eventBonuses||{}))t[k]+=v;return t};
dungeonEvent=function(){s.phase='event';const e=typeof s.event==='number'?eventCatalog[s.event]:s.eventSpec||eventCatalog[0];s.eventSpec=e;document.body.dataset.scene='event';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">DUNGEON EVENT ${e.id+1} / 100 · 区画${s.depth}</div><div class="seal">${icon(e.kind===7?'光':'汎用')}</div><h1 style="font-size:34px">${e.name}</h1><p>${e.text}</p>${dungeonHud()}<div class="event-choices">${eventChoices(e).map((c,i)=>`<button onclick="resolveDungeonEvent(${i})" ${s.gold<(c.cost||0)?'disabled':''}>${c.label}</button>`).join('')}</div></section>`};
resolveDungeonEvent=function(i){if(s.phase!=='event'||![0,1].includes(i))return;const c=eventChoices(s.eventSpec)[i];if(s.gold<(c.cost||0))return;s.phase='resolving';s.gold-=c.cost||0;if(c.shop){openDungeonShop();return}if(c.gamble){if(Math.random()<.5){s.gold+=30;s.earned+=30}else s.hp=Math.max(0,s.hp-5)}if(c.gold){s.gold+=c.gold;s.earned+=c.gold}if(c.damage)s.hp=Math.max(0,s.hp-c.damage);if(c.gems){queueCrystals(c.gems,'event')}if(c.card){const pool=all.filter(c=>['汎用',weapon,magic].includes(c.g));s.deck.push(eventReceiptCard??pool[Math.floor(Math.random()*pool.length)].id)}for(const key of ['attack','magic','maxHp'])if(c[key]){s.eventBonuses??={};s.eventBonuses[key]=(s.eventBonuses[key]||0)+c[key]}s.stats=characterStats();s.max=s.stats.maxHp;if(c.heal)s.hp=Math.min(s.max,s.hp+c.heal);if(!s.hp){finish(false);return}exploration(s.eventSpec.name+'：'+c.label+'。')};
const routeTemplates=[['静かな回廊',.3,0],['獣の足跡',.65,10],['血染めの石段',.85,20],['光る横穴',.4,5],['霧の迂回路',.2,0],['崩れた広間',.55,10],['古い地下道',.5,5],['風鳴りの通路',.35,0],['黒い門',.75,15],['水音の小径',.25,0]];
const contentExploration=exploration;exploration=function(message=''){s.routes=s.depth===11?[{name:'最深部の封印扉',boss:true}]:shuffle([...routeTemplates]).slice(0,1+Math.floor(Math.random()*3)).map(t=>({name:t[0],combat:t[1],bonus:t[2]}));contentExploration(message);let html=$('#app').innerHTML;const start=html.indexOf('<div class="explore-actions">'),end=html.indexOf('<p class="small">区画',start);const buttons=s.routes.map((r,i)=>`<button onclick="chooseDungeonRoute(${i})"><b>${r.name}</b><span>${r.boss?'最深部のボス':`戦闘率${Math.round(r.combat*100)}％ / 戦闘報酬＋${r.bonus} G`}</span></button>`).join('');html=html.slice(0,start)+'<div class="explore-actions">'+buttons+'</div>'+html.slice(end);html=html.replace('二つの道が続いている',s.routes.length+'本の道が続いている');$('#app').innerHTML=html};
function chooseDungeonRoute(i){if(s.phase!=='explore'||!Number.isInteger(i)||!s.routes[i])return;const r=s.routes[i];s.phase='travel';s.depth++;s.dangerBonus=r.bonus||0;if(r.boss){s.stage=3;s.encounters.push('ボス');battle();return}if(s.depth===6){s.encounters.push('行商人');openDungeonShop();return}if(s.depth===1||Math.random()<r.combat){s.stage=Math.min(2,Math.floor((s.depth-1)/4));s.encounters.push('戦闘');battle()}else{s.event=Math.floor(Math.random()*100);s.encounters.push('イベント');dungeonEvent()}}

const endlessStart=start;start=function(){endlessStart();s.layer=1;s.floorSteps=0;s.bossesWon=0;s.awaitingNextLayer=false;exploration()};
function bossRouteChance(){return Math.min(.6,.2+Math.max(0,(s.floorSteps||0)-8)*.04)}
exploration=function(message=''){s.layer??=1;s.floorSteps??=0;s.bossesWon??=0;s.phase='explore';s.pending=0;const count=1+Math.floor(Math.random()*3);s.routes=shuffle([...routeTemplates]).slice(0,count).map(t=>({name:t[0],combat:t[1],bonus:t[2]}));if(Math.random()<bossRouteChance())s.routes[Math.floor(Math.random()*count)]={name:'層の守護者の扉',boss:true};document.body.dataset.scene='explore';$('#app').innerHTML=`<section class="reward dungeon-explore"><div class="eyebrow">ENDLESS DUNGEON / LAYER ${s.layer}</div><h1 style="font-size:38px">第${s.layer}層 · 忘れられた遺跡</h1><p>終わりのない深淵へ。守護者を倒し、さらに下の層へ進む。</p>${dungeonHud()}<div class="dungeon-map">${s.encounters.slice(-12).map((e,i)=>`<span class="visited" title="${e}">${e==='ボス'?'♛':e==='戦闘'?'⚔':e==='行商人'?'G':'◇'}</span>`).join('')}<span class="current">?</span></div><div class="explore-scene"><img src="${artAssets.scene}" alt="霧に包まれた遺跡"><div><span class="eyebrow">${s.routes.some(r=>r.boss)?'THE GUARDIAN IS NEAR':'CHOOSE YOUR PATH'}</span><h2>${s.routes.length}本の道が続いている</h2><p>${s.routes.some(r=>r.boss)?'重い扉の奥から、守護者の気配を感じる。':'新しい部屋、魔物、あるいは思いがけない出会い。'}</p></div></div><p aria-live="polite">${message||'探索 → 戦闘・イベント → 探索。ボス勝利後は必ず次の層へ。'}</p><div class="explore-actions">${s.routes.map((r,i)=>`<button class="${r.boss?'primary':''}" onclick="chooseDungeonRoute(${i})"><b>${r.name}</b><span>${r.boss?'ボス戦 / 勝利後に次の層へ':`戦闘率${Math.round(r.combat*100)}％ / 戦闘報酬＋${r.bonus} G`}</span></button>`).join('')}</div><p class="small">この層の探索 ${s.floorSteps}回 ／ 累計探索 ${s.depth}回 ／ 戦闘勝利 ${s.battlesWon}回 ／ ボス撃破 ${s.bossesWon}体<br>ボスルート出現率 ${Math.round(bossRouteChance()*100)}％。長く探索すると出現率が上がります。<br>HP・ゴールド・デッキ・装備は次の層へ引き継ぎます。</p></section>`};
chooseDungeonRoute=function(i){if(s.phase!=='explore'||!Number.isInteger(i)||!s.routes[i])return;const r=s.routes[i];s.phase='travel';s.depth++;s.floorSteps++;s.dangerBonus=r.bonus||0;s.encounters=s.encounters.slice(-99);if(r.boss){s.stage=3;s.encounters.push('ボス');s.nextBattleSpec=shuffle(battleCatalog.filter(b=>b.boss))[0];battle();return}if(s.floorSteps%6===0){s.encounters.push('行商人');openDungeonShop();return}if(Math.random()<r.combat){s.stage=Math.min(2,Math.floor(s.floorSteps/4));s.encounters.push('戦闘');s.nextBattleSpec=shuffle(battleCatalog.filter(b=>!b.boss))[0];battle()}else{s.event=Math.floor(Math.random()*100);s.encounters.push('イベント');dungeonEvent()}};
const baseEndlessEnemies=encounterEnemies;encounterEnemies=function(spec){const originalDepth=s.depth;s.depth=1;const enemies=baseEndlessEnemies(spec);s.depth=originalDepth;const scaling=1+Math.max(0,(s.layer||1)-1)*.12;for(const e of enemies){e.hp=e.max=Math.round(e.hp*scaling);e.baseAttack=Math.max(1,Math.round(e.baseAttack*(1+Math.max(0,(s.layer||1)-1)*.08)))}return enemies};
winCheck=function(){if(s.phase!=='battle'||!s.enemies.every(e=>e.hp<=0))return false;const boss=!!s.encounterSpec?.boss;s.battlesWon++;if(boss)s.bossesWon++;s.phase='reward';s.pending=0;s.lastBounty=(boss?55:25+s.stage*10)+Math.max(0,s.layer-1)*5+(s.dangerBonus||0);s.dangerBonus=0;s.gold+=s.lastBounty;s.earned+=s.lastBounty;s.lastCrystals=(boss?15:3)+Math.floor(Math.max(0,s.layer-1)/3);queueCrystals(s.lastCrystals,'battle');s.hp=Math.min(s.max,s.hp+10);s.awaitingNextLayer=boss;s.reward=shuffle(all.filter(c=>['汎用',weapon,magic].includes(c.g)&&owned(c))).slice(0,3).map(c=>c.id);reward();if(boss){$('#app').innerHTML=$('#app').innerHTML.replace('新たな力を、手に。','第'+s.layer+'層の守護者を撃破！').replace('カードを取らずに進む →','カードを取らず第'+(s.layer+1)+'層へ →').replace('デッキに加えるカードを1枚選んでください。','カードを選ぶと、必ず第'+(s.layer+1)+'層へ進みます。')}return true};
next=function(id){if(s.phase!=='reward')return;if(id>=0){if(!s.reward.includes(id))return;s.deck.push(id)}if(s.awaitingNextLayer){s.layer++;s.floorSteps=0;s.awaitingNextLayer=false;s.eventSpec=null;openLayerMagicSelection()}else exploration('戦闘を終え、同じ層の探索に戻った。')};
const endlessRender=render;render=function(){endlessRender();$('#app').innerHTML=$('#app').innerHTML.replace('DUNGEON '+s.depth+' / '+dungeonLength,'LAYER '+s.layer+' / 探索 '+s.floorSteps)};
const endlessFinish=finish;finish=function(won){endlessFinish(won);$('#app').innerHTML=$('#app').innerHTML.replace('到達区画 '+s.depth+' / '+dungeonLength,'到達 第'+s.layer+'層 ／ 累計探索 '+s.depth+'回').replace('THE RUINS ARE LIBERATED','ENDLESS JOURNEY')};

const cursedPrefixes=['血盟','灰燼','夜葬','忘却','断罪','飢餓','喪失','亡国','禁忌','終焉'];
const cursedNames={武器:['の牙','の断頭刃','の哭槍','の葬弓','の骨槌','の影刃','の誓剣','の裂牙','の狩刃','の魔鋼'],装備:['の胸甲','の棘盾','の骸衣','の外套','の鎖帷子','の仮面','の黒鎧','の護肩','の喪服','の鉄壁'],アクセサリー:['の指環','の呪符','の首飾り','の腕輪','の耳飾り','の心珠','の印章','の牙飾り','の鎖環','の涙石']};
const cursedAdditionalCosts=[{defense:-1},{magic:-2},{attack:-2},{healing:-2},{maxEnergy:-1},{maxMana:-1},{defense:-2,healing:-1},{magic:-1,attack:-1}];
for(const [type,tag] of [['武器','weapon'],['装備','armor'],['アクセサリー','accessory']])for(let i=0;i<100;i++){const rank=2+Math.floor(i/20),power=5+rank*2,stats=type==='武器'?{attack:power}:type==='装備'?(i%2?{magic:power,defense:2}:{defense:3+rank,attack:3}):(i%3===0?{healing:power}:i%3===1?{magic:power}:{attack:power}),penalties={maxHp:-(5+rank*2),...cursedAdditionalCosts[i%8]};gearCards.push({id:'cursed-'+tag+'-'+i,type,group:type==='武器'?weapons[i%6]:type==='装備'?'防御':'汎用',element:type==='武器'?magics[Math.floor(i/6)%7]:undefined,elementPower:type==='武器'?rank:undefined,name:cursedPrefixes[Math.floor(i/10)]+cursedNames[type][i%10],rank,stats,penalties,cursed:true,gold:45+rank*20,crystals:12+rank*6})}
const costStatLabels={attack:'攻撃力',magic:'魔力',defense:'防御力',maxHp:'最大HP',healing:'回復力',maxEnergy:'行動上限',maxMana:'マナ上限'};
const statsBeforeCurses=characterStats;characterStats=function(){const stats=statsBeforeCurses();for(const id of currentGearIds()){const c=gearCards.find(c=>c.id===id);if(c?.type==='武器'&&c.group!==weapon)continue;for(const [key,value] of Object.entries(c?.penalties||{}))stats[key]+=value;}stats.maxHp=Math.max(1,stats.maxHp);stats.maxEnergy=Math.max(1,stats.maxEnergy);stats.maxMana=Math.max(1,stats.maxMana);stats.healing=Math.max(0,stats.healing);stats.attack=Math.max(0,stats.attack);stats.magic=Math.max(0,stats.magic);return stats};
const gearTextBeforeCurses=gearText;gearText=function(c){return gearTextBeforeCurses(c)+(c.cursed?'<br><span class="gear-penalty">代償：'+Object.entries(c.penalties).map(([k,v])=>costStatLabels[k]+'−'+Math.abs(v)).join(' / ')+'</span>':'')};
let gearRiskFilter='all';
const gearVisibleBeforeCurses=visibleGearCards;visibleGearCards=function(){return gearVisibleBeforeCurses().filter(c=>gearRiskFilter==='all'||gearRiskFilter==='cursed'&&c.cursed||gearRiskFilter==='normal'&&!c.cursed)};
const gearControlsBeforeCurses=gearFilterControls;gearFilterControls=function(){return gearControlsBeforeCurses()+`<div class="market-controls"><label>カードの性質 <select onchange="gearRiskFilter=this.value;gearPage=0;gearPanel()">${[['all','全カード'],['normal','代償なし'],['cursed','代償あり']].map(([key,text])=>`<option value="${key}" ${gearRiskFilter===key?'selected':''}>${text}</option>`).join('')}</select></label><span class="small">代償は装着中のみ発動。HP・行動・マナの上限は最低1、攻撃力・魔力・回復力は最低0です。</span></div>`};
if(new Set(gearCards.map(c=>c.name)).size!==gearCards.length)throw Error('装着カード名の重複');

const primaryStats=[['STR','筋力'],['DEX','器用さ'],['AGI','敏捷性'],['POW','精神力'],['VIT','生命力'],['INT','知力']];
function cleanPrimaryStats(data){return Object.fromEntries(primaryStats.map(([key])=>[key,Number.isSafeInteger(data?.[key])&&data[key]>=0?Math.min(9999,data[key]):10]))}
const statsBeforePrimary=characterStats;characterStats=function(){const stats=statsBeforePrimary();Object.assign(stats,cleanPrimaryStats(meta.primaryStats));return stats};
const summaryBeforePrimary=statSummary;statSummary=function(){const stats=s?.stats||characterStats();return `<div class="primary-stats" aria-label="基本能力値">${primaryStats.map(([key,label])=>`<div title="${label}"><span>${key}</span><strong>${stats[key]??10}</strong><small>${label}</small></div>`).join('')}</div>`+summaryBeforePrimary()};

const weaponAttribute={片手剣:'STR',大剣:'STR',短剣:'DEX',弓:'DEX',槍:'AGI',戦槌:'STR'};
for(const b of skillBranches)for(const n of b.nodes){n.primaryBonus={};for(const [key,value] of Object.entries(n[4])){const attr=key==='attack'?(b.weapon?weaponAttribute[b.weapon]:'STR'):key==='magic'?'INT':key==='defense'||key==='maxHp'?'VIT':key==='maxEnergy'?'AGI':'POW';n.primaryBonus[attr]=(n.primaryBonus[attr]||0)+(key==='maxHp'?Math.max(1,Math.ceil(value/5)):value);}n[3]+=' / '+Object.entries(n.primaryBonus).map(([k,v])=>k+'＋'+v).join('、');}
for(const c of gearCards){if(c.type==='アクセサリー')continue;const amount=10+c.rank*3+(c.cursed?2:0);c.requirements=c.type==='武器'?{[weaponAttribute[c.group]]:amount}:{VIT:amount};if(c.element)c.requirements[c.element==='光'||c.element==='闇'?'POW':'INT']=10+c.rank*2;}
function coreAttributes(){const t=cleanPrimaryStats(meta.primaryStats);for(const [k,v] of Object.entries(s?.levelAttributes||{}))t[k]+=v;for(const [k,v] of Object.entries(s?.eventAttributes||{}))t[k]+=v;for(const b of skillBranches){if(b.weapon&&b.weapon!==weapon||b.magic&&b.magic!==magic)continue;for(const n of b.nodes)if((meta.skills||[]).includes(n[0]))for(const [k,v] of Object.entries(n.primaryBonus||{}))t[k]+=v;}return t}
function meetsGear(c){const t=coreAttributes();return Object.entries(c.requirements||{}).every(([k,v])=>t[k]>=v)}
const priorLevelStats=characterStats;
characterStats=function(){ensureGear();const l=s?.loadout||meta.loadout;const saved={weapon:l.weapon,armor:[...l.armor],accessories:[...l.accessories]};const wc=gearCards.find(c=>c.id===l.weapon);if(wc&&!meetsGear(wc))l.weapon='weapon-'+weapon+'-0';l.armor=l.armor.filter(id=>meetsGear(gearCards.find(c=>c.id===id)));let t;try{t=priorLevelStats()}finally{l.weapon=saved.weapon;l.armor=saved.armor;l.accessories=saved.accessories}const a=coreAttributes();Object.assign(t,a);t.attack+=Math.floor(Math.max(0,a.STR-10)/2);t.magic+=Math.floor(Math.max(0,a.INT-10)/2);t.defense+=Math.floor(Math.max(0,a.VIT-10)/5);t.maxHp+=Math.max(0,a.VIT-10)*5;t.healing+=Math.floor(Math.max(0,a.POW-10)/3);t.maxEnergy+=Math.min(2,Math.floor(Math.max(0,a.AGI-10)/10));t.maxMana+=Math.min(2,Math.floor(Math.max(0,a.POW-10)/10));t.penetration=Math.floor(Math.max(0,a.DEX-10)/5);t.dodge=Math.min(.25,Math.max(0,a.AGI-10)*.01);return t};
const originalLevelEquip=equipGear;equipGear=function(id){const c=gearCards.find(c=>c.id===id);if(!c)return;if(!meetsGear(c)){gearPanel('要求値が不足しています：'+Object.entries(c.requirements).map(([k,v])=>k+' '+v).join(' / '));return}originalLevelEquip(id)};
const originalLevelGearText=gearText;gearText=function(c){return originalLevelGearText(c)+(c.requirements?'<br><span class="gear-requirement">要求：'+Object.entries(c.requirements).map(([k,v])=>k+' '+v).join(' / ')+' · '+(meetsGear(c)?'条件達成':'不足・装着効果無効')+'</span>':'')};
function xpNeeded(){return 20+(s.level-1)*10}
function gainXp(amount){if(!s)return;s.xp+=amount;s.totalXp+=amount;s.lastXp=amount;let ups=0;while(s.xp>=xpNeeded()){s.xp-=xpNeeded();s.level++;s.statPoints+=3;ups++;}if(ups){const oldMax=s.max;s.stats=characterStats();s.max=s.stats.maxHp;s.hp=Math.min(s.max,s.hp+Math.max(0,s.max-oldMax));}return ups}
const originalLevelStart=start;start=function(){s=null;originalLevelStart();s.level=1;s.xp=0;s.totalXp=0;s.statPoints=0;s.levelAttributes={};s.eventAttributes={};s.stats=characterStats();s.max=s.stats.maxHp;s.hp=s.max;exploration()};
const originalLevelWin=winCheck;winCheck=function(){if(s.phase!=='battle'||!s.enemies.every(e=>e.hp<=0))return false;const xp=(s.encounterSpec?.boss?40:12)+(s.layer-1)*4;gainXp(xp);const result=originalLevelWin();if(result)$('#app').innerHTML+='<p class="hint">経験値＋'+xp+' ／ Lv '+s.level+' ／ 未使用能力ポイント '+s.statPoints+'</p>';return result};
const originalLevelEvent=resolveDungeonEvent;resolveDungeonEvent=function(i){if(s.phase!=='event')return;const choice=eventChoices(s.eventSpec)[i];if(!choice||s.gold<(choice.cost||0))return;const eventKind=s.eventSpec.kind;gainXp(5+s.layer);if([5,6,7,8].includes(eventKind)){const attr={5:'INT',6:'STR',7:'POW',8:'VIT'}[eventKind];s.eventAttributes[attr]=(s.eventAttributes[attr]||0)+1;}originalLevelEvent(i)};
function spendStat(key){if(!s||s.phase==='battle'||!primaryStats.some(([k])=>k===key)||s.statPoints<1)return;s.statPoints--;s.levelAttributes[key]=(s.levelAttributes[key]||0)+1;const before=s.max;s.stats=characterStats();s.max=s.stats.maxHp;s.hp=Math.min(s.max,s.hp+Math.max(0,s.max-before));levelPanel()}
function levelPanel(){if(!s){alert('Lvと能力ポイントは冒険開始後に利用できます。');return}const t=s.stats;$('#app').innerHTML=`<section class="reward"><div class="eyebrow">ADVENTURER / LEVEL ${s.level}</div><h1 style="font-size:36px">Lv ${s.level} · 能力振り分け</h1><p>経験値 ${s.xp} / ${xpNeeded()} ／ 能力ポイント ${s.statPoints}<br>レベルアップごとに3ポイント。Lv・経験値・振り分けは今回の冒険限定です。</p><div class="primary-stats">${primaryStats.map(([k,label])=>`<div><span>${k}</span><strong>${t[k]}</strong><small>${label}</small><button onclick="spendStat('${k}')" ${s.statPoints<1||s.phase==='battle'?'disabled':''}>＋1</button></div>`).join('')}</div>${statSummary()}<p class="small">STR：10超過分2ごとに攻撃力＋1<br>DEX：10超過分5ごとに攻撃時の敵防御を1削る<br>AGI：10超過分1ごとに回避率＋1％（最大25％）、10ごとに行動上限＋1（最大＋2）<br>POW：10超過分3ごとに回復力＋1、10ごとにマナ上限＋1（最大＋2）<br>VIT：10超過分1ごとに最大HP＋5、5ごとに防御力＋1<br>INT：10超過分2ごとに魔力＋1<br>装備の要求は基本値10＋今回のLv振り分けで判定します。熟練度と習得スキルは持ち越します。<br>要求不足の装備は所持・装着記録を残し、効果だけを停止します。</p><button onclick="returnFromLevel()">戻る →</button></section>`}
function returnFromLevel(){if(s.phase==='explore')exploration();else if(s.phase==='shop')shop();else if(s.phase==='reward')reward();else if(s.phase==='event')dungeonEvent();else if(s.phase==='battle')render();else finish(false)}
const originalLevelHud=dungeonHud;dungeonHud=function(){return originalLevelHud()+`<p class="hint">Lv ${s.level||1} ／ EXP ${s.xp||0} / ${s.level?xpNeeded():20} <button onclick="levelPanel()">能力振り分け（${s.statPoints||0}）</button></p>`};
const originalLevelSummary=statSummary;statSummary=function(){return (s?`<div class="hint">Lv ${s.level||1} ／ EXP ${s.xp||0} / ${s.level?xpNeeded():20} ／ 回避率 ${Math.round((s.stats.dodge||0)*100)}％</div>`:'')+originalLevelSummary()};

const cardBeforeLevels=card;card=function(c,action,disabled=false){let html=cardBeforeLevels(c,action,disabled);const stats=s?.stats||characterStats();let text='';if(c.e.hit){const boost=magics.includes(c.g)?stats.magic+(stats.elementMagic||0):stats.attack;text=`<span class="card-scaling">${magics.includes(c.g)?'INT・魔力':'STR・攻撃力'}補正 ＋${boost}${!magics.includes(c.g)&&stats.penetration?' / 防御削り '+stats.penetration:''}</span>`}else if(c.e.heal)text=`<span class="card-scaling">POW・回復力補正 ＋${stats.healing}</span>`;return html.replace('<span class="desc">','<span class="desc">'+text)};

const startingGold=300,initialDeckMinimum=5,initialDeckSize=10,maximumDeckSize=15,initialCardPrices=[10,15,25,40,60,80,100];
for(const c of all)c.rarityRank=c.exclusive?Math.floor((c.id-70)/10)%7:c.n.startsWith('奥義')?4:Math.min(2,c.c);
function initialDeckCost(){return picks.reduce((sum,id)=>sum+initialCardPrices[all[id].rarityRank],0)}
function deckLimit(){return maximumDeckSize+(s?.layer||1)}
function tryAddDeckCard(id){if(!all[id]||s.deck.length>=deckLimit())return false;s.deck.push(id);return true}
let initialDeckPage=0;
deckSetup=function(){s=null;initialDeckPage=0;picks=[];deckRender()};
deckRender=function(message=''){document.body.dataset.scene='deck';const pool=all.filter(c=>['汎用',weapon,magic].includes(c.g)&&owned(c)),cost=initialDeckCost(),pages=Math.max(1,Math.ceil(pool.length/15));initialDeckPage=Math.max(0,Math.min(initialDeckPage,pages-1));$('#app').innerHTML=`<section class="hero"><div class="eyebrow">STARTING DECK / GOLD ${startingGold}</div><h1 style="font-size:36px">旅立ちのカード購入</h1><p>開始資金 ${startingGold} G ／ 選択 ${picks.length} / ${initialDeckSize}枚<br>購入合計 ${cost} G ／ 出発後の所持金 ${startingGold-cost} G<br>初期デッキは${initialDeckMinimum}〜${initialDeckSize}枚を選択。冒険中の上限は${maximumDeckSize}＋現在の階層です。</p><div class="initial-prices">${rarities.map((r,i)=>`<span style="color:${r[1]}">${r[0]} ${initialCardPrices[i]} G</span>`).join('')}</div><button class="primary" onclick="start()" ${picks.length<initialDeckMinimum||picks.length>initialDeckSize||cost>startingGold?'disabled':''}>購入して出発 →</button> <button onclick="setup()">装備を変更</button><p aria-live="polite">${message}</p></section><div class="cards">${pool.slice(initialDeckPage*15,(initialDeckPage+1)*15).map(c=>`<div class="shop-item">${card(c,`togglePick(${c.id})`)}<button class="${picks.includes(c.id)?'chosen':''}" onclick="togglePick(${c.id})">${picks.includes(c.id)?'選択済み · 外す':rarities[c.rarityRank][0]+' / '+initialCardPrices[c.rarityRank]+' G'}</button></div>`).join('')}</div><div class="market-pagination"><button onclick="initialDeckPage--;deckRender()" ${initialDeckPage===0?'disabled':''}>← 前へ</button><span>${initialDeckPage+1} / ${pages}</span><button onclick="initialDeckPage++;deckRender()" ${initialDeckPage>=pages-1?'disabled':''}>次へ →</button></div>`};
togglePick=function(id){if(!all[id]||!owned(all[id])||!['汎用',weapon,magic].includes(all[id].g))return;if(picks.includes(id))picks=picks.filter(x=>x!==id);else{if(picks.length>=initialDeckSize){deckRender('初期デッキは'+initialDeckSize+'枚まで選択できます。');return}if(initialDeckCost()+initialCardPrices[all[id].rarityRank]>startingGold){deckRender('開始資金が不足しています。');return}picks.push(id)}deckRender()};
const budgetStart=start;start=function(){if(s||picks.length<initialDeckMinimum||picks.length>initialDeckSize||initialDeckCost()>startingGold||new Set(picks).size!==picks.length||picks.some(id=>!all[id]||!owned(all[id])||!['汎用',weapon,magic].includes(all[id].g)))return;const cost=initialDeckCost();budgetStart();s.gold=startingGold-cost;s.initialCost=cost;exploration('開始資金'+startingGold+' Gから、初期デッキを'+cost+' Gで購入した。')};
const budgetBuyCard=buyCard;buyCard=function(i){if(s?.phase!=='shop')return;if(s.deck.length>=deckLimit()){s.shopMessage='デッキ上限です。デッキ整理で空きを作ってください。';shop();return}budgetBuyCard(i)};
const budgetNext=next;next=function(id){if(s?.phase!=='reward')return;if(id>=0&&s.deck.length>=deckLimit()){s.messages.unshift('デッキ上限のため、カードを受け取れません。');reward();return}budgetNext(id)};
