const budgetHud=dungeonHud;dungeonHud=function(){return budgetHud()+`<p class="hint">デッキ ${s.deck.length} / ${deckLimit()}枚 <button onclick="manageDeck()">デッキ整理</button></p>`};
function manageDeck(){if(!s||!['explore','shop','reward'].includes(s.phase))return;$('#app').innerHTML=`<section class="reward"><div class="eyebrow">DECK MANAGEMENT</div><h1 style="font-size:34px">デッキ整理</h1><p>${s.deck.length} / ${deckLimit()}枚 ／ 最小5枚<br>カードを選ぶと今回のデッキから外します。永続解放は保持されます。購入代金は戻りません。</p><div class="cards">${s.deck.map((id,i)=>card(all[id],`removeDeckCard(${i})`,s.deck.length<=5)).join('')}</div><button onclick="returnFromDeck()">戻る →</button></section>`}
function removeDeckCard(i){if(!s||!['explore','shop','reward'].includes(s.phase)||s.deck.length<=5||!Number.isInteger(i)||i<0||i>=s.deck.length)return;s.deck.splice(i,1);manageDeck()}
