function cleanMastery(data){return Object.fromEntries(weapons.map(w=>[w,Number.isSafeInteger(data?.[w])&&data[w]>=0?Math.min(1000000,data[w]):0]))}
function weaponMastery(w=weapon){return cleanMastery(meta.mastery)[w]}
for(const b of skillBranches)for(const n of b.nodes){n.primaryBonus={};n.masteryRequirement=skillDepth(n[0])*20;n[3]=n[3].split(' / ')[0]+' / 熟練度 '+n.masteryRequirement+'で発動';}
coreAttributes=function(){const values=Object.fromEntries(primaryStats.map(([k])=>[k,10]));for(const [k,v] of Object.entries(s?.levelAttributes||{}))values[k]+=v;return values};
const statsBeforeMasteryRules=characterStats;characterStats=function(){const oldSkills=meta.skills,oldPrimary=meta.primaryStats,oldUpgrades=meta.hpUpgrades,oldEvents=s?.eventBonuses;meta.skills=(meta.skills||[]).filter(id=>{const f=skillById(id);return f&&skillProficiency(f.branch)>=f.node.masteryRequirement});meta.primaryStats=Object.fromEntries(primaryStats.map(([k])=>[k,10]));meta.hpUpgrades=0;if(s)s.eventBonuses={};try{return statsBeforeMasteryRules()}finally{meta.skills=oldSkills;meta.primaryStats=oldPrimary;meta.hpUpgrades=oldUpgrades;if(s)s.eventBonuses=oldEvents}};
const masteryLearn=learnSkill;learnSkill=function(id){const f=skillById(id);if(!f)return;if(skillProficiency(f.branch)<f.node.masteryRequirement){skillTree('武器熟練度が不足しています。必要値：'+f.node.masteryRequirement);return}masteryLearn(id)};
const masteryTree=skillTree;skillTree=function(message=''){masteryTree(message);const f=skillById(selectedSkill);if(f&&document.body.dataset.scene==='skills')$('#app').innerHTML+='<p class="hint">'+(f.branch.magic||f.branch.weapon|| (f.branch.name==='星の道'?magic:weapon))+'熟練度 '+skillProficiency(f.branch)+' ／ このスキルの要求 '+f.node.masteryRequirement+'<br>STRなどの6能力値はLvアップだけで上昇します。スキルは熟練条件達成時に戦闘能力の補正を発動します。</p>'};
function masteryPanel(){const content=`<section class="reward"><div class="eyebrow">WEAPON PROFICIENCY</div><h1 style="font-size:36px">武器熟練度</h1><p>使用中の武器で勝利すると＋10、ボス勝利なら＋30。<br>熟練度はプロフィールに保存します。Lv・6能力値は持ち越しません。</p><div class="character-stats">${weapons.map(w=>`<div><span>${w}</span><strong>${weaponMastery(w)}</strong></div>`).join('')}</div><p class="small">スキルは、前提スキルと必要熟練度を満たすと魔晶石で習得できます。</p><button onclick="${s?'returnFromLevel()':'setup()'}">戻る →</button></section>`;$('#app').innerHTML=content}
const masteryWin=winCheck;winCheck=function(){if(s?.phase!=='battle'||!s.enemies.every(e=>e.hp<=0))return false;meta.mastery=cleanMastery(meta.mastery);const gain=s.encounterSpec?.boss?30:10;meta.mastery[weapon]+=gain;saveMeta();const done=masteryWin();if(done)$('#app').innerHTML+='<p class="hint">'+weapon+'熟練度＋'+gain+'（合計 '+weaponMastery()+'）</p>';return done};
const masteryEventChoices=eventChoices;eventChoices=function(e){return masteryEventChoices(e).map(c=>{const out={...c};for(const key of ['attack','magic','maxHp'])if(out[key]){delete out[key];out.extraXp=(out.extraXp||0)+10;out.label=out.label.replace(/今回の攻撃力＋1|今回の魔力＋1|最大HP＋3/g,'経験値＋10')}return out})};
const masteryEventResolve=resolveDungeonEvent;resolveDungeonEvent=function(i){if(s?.phase!=='event')return;const c=eventChoices(s.eventSpec)[i];if(!c||s.gold<(c.cost||0)||c.card&&s.deck.length>=deckLimit())return;if(c.extraXp)gainXp(c.extraXp);masteryEventResolve(i)};
const originalInitialGear=starterGear.slice();starterGear.splice(0,starterGear.length,...gearCards.filter(c=>c.type==='武器'&&!c.element&&c.rank===0).map(c=>c.id));
ensureGear=function(){meta.gearOwned=[...starterGear];meta.loadout={weapon:'weapon-'+weapon+'-0',armor:[],accessories:[]}};
const masteryEquip=equipGear;equipGear=function(id){if(!s){if(starterGear.includes(id)){weapon=gearCards.find(c=>c.id===id).group;setup()}return}masteryEquip(id)};
const masteryBuy=buyGear;buyGear=function(id){if(!s||s.phase!=='shop')return;masteryBuy(id)};
const masteryGearPanel=gearPanel;gearPanel=function(message=''){if(!s){ensureGear();$('#app').innerHTML=`<section class="reward"><div class="eyebrow">STARTING WEAPONS</div><h1 style="font-size:36px">初期武器</h1><p>冒険前に使えるのは初期武器だけです。<br>それ以外の武器・装備・アクセサリーは、探索イベントや冒険中のショップで入手します。</p><div class="choices gear-tabs">${weapons.map(w=>`<button class="${w===weapon?'chosen':''}" onclick="weapon='${w}';gearPanel()">${w}</button>`).join('')}</div><button onclick="setup()">冒険の準備へ →</button></section>`;return}masteryGearPanel(message)};
const masteryStart=start;start=function(){if(s)return;ensureGear();masteryStart();if(s){s.loadout={weapon:'weapon-'+weapon+'-0',armor:[],accessories:[]};s.gearOwned=[];s.levelAttributes={};s.eventAttributes={};s.eventBonuses={};s.stats=characterStats();s.max=s.stats.maxHp;s.hp=s.max;exploration('初期武器を手に、今回の冒険を始めた。')}};
const masterySetup=setup;setup=function(){masterySetup();$('#app').innerHTML=$('#app').innerHTML.replace('<div class="legacy-summary">','<div class="legacy-summary"><button onclick="masteryPanel()">武器熟練度</button>')};
const masteryHud=dungeonHud;dungeonHud=function(){return masteryHud()+`<p class="hint">${weapon}熟練度 ${weaponMastery()} <button onclick="masteryPanel()">熟練度を見る</button></p>`};
