crystalExchange=function(){if(s)return;document.body.dataset.scene='exchange';$('#app').innerHTML=`<section class="reward"><div class="eyebrow">CRYSTAL SANCTUARY</div><h1 style="font-size:36px">魔晶石交換所</h1><p>魔晶石は、戦闘カードの永続解放とスキル習得に使えます。</p><span class="crystal-badge">◇ ${meta.crystals} 魔晶石</span><p><button onclick="cardCollection()">戦闘カードを永続解放</button> <button onclick="skillTree()">スキルツリー</button> <button onclick="masteryPanel()">武器熟練度</button></p><p class="small">装着カードは冒険中に入手。Lv・6能力値・装着カードは次の冒険に持ち越しません。</p><button onclick="setup()">冒険の準備へ →</button></section>`};
function cleanMagicMastery(d){return Object.fromEntries(magics.map(m=>[m,Number.isSafeInteger(d?.[m])&&d[m]>=0?Math.min(1000000,d[m]):0]))}
function magicMastery(m=magic){return cleanMagicMastery(meta.magicMastery)[m]}
function skillProficiency(b){return b.magic||b.name==='星の道'?magicMastery(b.magic||magic):weaponMastery(b.weapon||weapon)}
const magicMasteryStats=characterStats;characterStats=function(){const stats=magicMasteryStats();stats.magic+=Math.min(20,Math.floor(magicMastery()/50));return stats};
const recordMagicPlay=play;play=function(i){if(s?.phase==='battle'&&!s.pending){const c=all[s.hand[i]];if(c&&magics.includes(c.g)&&can(c)&&s.enemies[s.target]?.hp>0){s.usedMagic??={};s.usedMagic[c.g]=(s.usedMagic[c.g]||0)+1;}}recordMagicPlay(i)};
const magicMasteryBattle=battle;battle=function(){s.usedMagic={};magicMasteryBattle()};
const magicMasteryWin=winCheck;winCheck=function(){if(s?.phase!=='battle'||!s.enemies.every(e=>e.hp<=0))return false;meta.magicMastery=cleanMagicMastery(meta.magicMastery);const gain=s.encounterSpec?.boss?30:10,used=magics.filter(m=>s.usedMagic?.[m]>0);for(const m of used)meta.magicMastery[m]+=gain;if(used.length)saveMeta();const result=magicMasteryWin();if(result&&used.length)$('#app').innerHTML+='<p class="hint">'+used.map(m=>m+'魔法熟練度＋'+gain).join(' / ')+'</p>';return result};
const priorMasteryPanel=masteryPanel;masteryPanel=function(){priorMasteryPanel();$('#app').innerHTML+='<h2 style="text-align:center">魔法熟練度</h2><div class="character-stats">'+magics.map(m=>'<div><span>'+m+'</span><strong>'+magicMastery(m)+'</strong></div>').join('')+'</div><p class="hint">その戦闘で使用した属性だけ、通常勝利＋10・ボス勝利＋30。50ごとに魔力＋1（最大＋20）。魔法スキルも対応属性の熟練度で判定します。</p>'};
const magicCardPrefixes={火:['火蜥蜴','紅蓮鳥','火山王','燎原','灰燼','焔獅子','赤星','熾天','焦熱','炎帝'],氷:['氷狐','霜竜','凍海王','白雪','氷河','雪狼','寒星','銀霧','零界','冬帝'],雷:['雷鳥','紫電竜','雷雲王','轟鳴','電光','雷獣','嵐星','鳴神','天雷','雷帝'],風:['風燕','翠翼竜','嵐空王','旋風','蒼羽','風精','流星','天風','空鳴','風帝'],土:['岩亀','黒曜竜','地脈王','砂塵','琥珀','石獣','山星','金剛','大地','地帝'],光:['白鳩','聖光竜','日輪王','黎明','祈願','天使','聖星','祝福','白耀','光帝'],闇:['影鴉','冥月竜','深淵王','夜霧','幽冥','夜魔','暗星','魔眼','虚無','闇帝']};
const magicCardForms=['の射矢','の障壁','の波動','の祝祷','の双撃','の呪印','の導き','の逆流','の結界','の秘奥'];
for(const m of magics)for(let i=0;i<100;i++){const rank=Math.min(6,Math.floor(i/15)),f=i%10,p=rank%3;let effect,cost=1;switch(f){case 0:effect={hit:6+p};break;case 1:effect={block:7+p};break;case 2:cost=2;effect={hit:6+p,all:1};break;case 3:effect={heal:4+p};break;case 4:cost=2;effect={hit:4+p,times:2};break;case 5:effect={hit:3+p,weak:3};break;case 6:effect={draw:1,magicBuff:m==='雷'?3:0,buff:m==='雷'?0:3};break;case 7:cost=2;effect={hit:8+p,drain:1};break;case 8:cost=2;effect={block:10+p,cleanse:1};break;default:cost=3;effect={hit:16+p*2};}
if(m==='火'&&effect.hit&&!effect.times)effect.burn=2;if(m==='氷'&&effect.hit)effect.weak=(effect.weak||0)+2;if(m==='雷'&&effect.hit)effect.hit+=2;if(m==='風'&&f===6)effect={draw:1,discount:1};if(m==='土'&&effect.block){effect.block+=2;effect.carry=2}if(m==='光'&&effect.heal)effect.heal+=2;if(m==='闇'&&effect.hit)effect.hpCost=2;
add(m,m+'術・'+magicCardPrefixes[m][Math.floor(i/10)]+magicCardForms[f],cost,effectText(effect),effect);const card=all[all.length-1];Object.assign(card,{exclusive:true,rarityRank:rank,goldPrice:20+cost*10,crystalPrice:4+rank*3});}

